#include "shape_scanline_fill.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#define RASTER_FILL_SCANLINE_PIXEL_RUN_LIMIT (8U * 1024U * 1024U)

static const double sample_y_offsets[RASTER_FILL_SCANLINE_SAMPLE_ROWS] = {
    0.125, 0.375, 0.5, 0.625, 0.875
};

static bool checked_add_size(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool checked_mul_size(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static bool shape_is_uniform_filled(const svg_shape_document *document,
                                    size_t shape)
{
    if (document == NULL || shape >= document->shape_count ||
        document->shape_filled == NULL || !document->shape_filled[shape] ||
        document->shape_edge_start == NULL || document->shape_edge_count == NULL ||
        document->colors == NULL || document->strokes == NULL) return false;
    const svg_shape_stroke *stroke = &document->strokes[shape];
    if (stroke->rgba[3] != 0U && stroke->width > 0.0) return false;
    size_t first = document->shape_edge_start[shape];
    size_t count = document->shape_edge_count[shape];
    if (count == 0U || first > document->edge_count ||
        count > document->edge_count - first) return false;
    const uint8_t *color = document->colors + first * 4U;
    for (size_t edge = 1U; edge < count; edge++) {
        if (memcmp(color, document->colors + (first + edge) * 4U, 4U) != 0)
            return false;
    }
    return true;
}

static bool pixel_is_fully_in_view(const svg_shape_document *document,
                                   uint32_t x, uint32_t y,
                                   double scale_x, double scale_y,
                                   double offset_x, double offset_y)
{
    double content_width = document->view_width * scale_x;
    double content_height = document->view_height * scale_y;
    return (double)x >= offset_x && (double)y >= offset_y &&
           (double)x + 1.0 <= offset_x + content_width &&
           (double)y + 1.0 <= offset_y + content_height;
}

static bool crossing_less(const raster_fill_scanline_crossing *left,
                          const raster_fill_scanline_crossing *right)
{
    if (left->x < right->x) return true;
    if (left->x > right->x) return false;
    return left->edge_index < right->edge_index;
}

static void swap_crossings(raster_fill_scanline_crossing *left,
                           raster_fill_scanline_crossing *right)
{
    raster_fill_scanline_crossing temporary = *left;
    *left = *right;
    *right = temporary;
}

static void sift_down(raster_fill_scanline_crossing *values, size_t root,
                      size_t count)
{
    while (root < count / 2U) {
        size_t child = root * 2U + 1U;
        if (child + 1U < count && crossing_less(&values[child],
                                                &values[child + 1U]))
            child++;
        if (!crossing_less(&values[root], &values[child])) return;
        swap_crossings(&values[root], &values[child]);
        root = child;
    }
}

static void sort_crossings(raster_fill_scanline_crossing *values, size_t count)
{
    for (size_t parent = count / 2U; parent != 0U; parent--)
        sift_down(values, parent - 1U, count);
    for (size_t end = count; end > 1U; end--) {
        swap_crossings(&values[0], &values[end - 1U]);
        sift_down(values, 0U, end - 1U);
    }
}

static size_t ceil_log2(size_t value)
{
    size_t levels = 0U;
    size_t power = 1U;
    while (power < value) {
        if (power > SIZE_MAX / 2U) return sizeof(size_t) * 8U;
        power *= 2U;
        levels++;
    }
    return levels;
}

static bool build_intervals(const svg_shape_document *document, size_t shape,
                            double sample_y, const uint32_t *active_edges,
                            size_t active_count,
                            raster_fill_scanline_crossing *crossings,
                            size_t crossing_capacity,
                            raster_fill_scanline_interval *intervals,
                            size_t interval_capacity, size_t *out_interval_count,
                            size_t *out_edge_visits, size_t *out_work_units)
{
    *out_interval_count = 0U;
    if (active_count > crossing_capacity ||
        (active_count != 0U && active_edges == NULL)) return false;
    size_t crossing_count = 0U;
    for (size_t index = 0U; index < active_count; index++) {
        uint32_t edge_index = active_edges[index];
        if ((size_t)edge_index >= document->edge_count) return false;
        geom_edge edge = document->edges[edge_index];
        bool upward = edge.a.y <= sample_y && edge.b.y > sample_y;
        bool downward = edge.b.y <= sample_y && edge.a.y > sample_y;
        if (!upward && !downward) continue;
        double x = edge.a.x + (sample_y - edge.a.y) *
                   (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
        if (!isfinite(x)) return false;
        crossings[crossing_count++] = (raster_fill_scanline_crossing){
            x, upward ? 1 : -1, edge_index};
    }
    if (crossing_count > 1U) sort_crossings(crossings, crossing_count);
    int64_t winding = 0;
    uint8_t parity = 0U;
    for (size_t index = 0U; index < crossing_count; index++) {
        winding += crossings[index].winding_delta;
        parity ^= 1U;
    }
    if (crossing_count != 0U &&
        (document->shape_evenodd[shape] ? parity != 0U : winding != 0)) {
        if (interval_capacity == 0U) return false;
        intervals[(*out_interval_count)++] =
            (raster_fill_scanline_interval){-INFINITY, crossings[0].x};
    }
    size_t first = 0U;
    while (first < crossing_count) {
        size_t end = first + 1U;
        int64_t group_winding = crossings[first].winding_delta;
        uint8_t group_parity = 1U;
        while (end < crossing_count && crossings[end].x == crossings[first].x) {
            group_winding += crossings[end].winding_delta;
            group_parity ^= 1U;
            end++;
        }
        winding -= group_winding;
        parity ^= group_parity;
        double right = end < crossing_count ? crossings[end].x : INFINITY;
        bool inside = document->shape_evenodd[shape] ? parity != 0U : winding != 0;
        if (inside && crossings[first].x < right) {
            if (*out_interval_count >= interval_capacity) return false;
            intervals[(*out_interval_count)++] =
                (raster_fill_scanline_interval){crossings[first].x, right};
        }
        first = end;
    }
    *out_edge_visits = active_count;
    size_t sort_levels = ceil_log2(crossing_count > 1U ? crossing_count : 1U);
    size_t per_crossing, sort_work, scan_work;
    if (!checked_mul_size(sort_levels, 2U, &per_crossing) ||
        !checked_add_size(per_crossing, 6U, &per_crossing) ||
        !checked_mul_size(crossing_count, per_crossing, &sort_work) ||
        !checked_mul_size(active_count, 2U, &scan_work) ||
        !checked_add_size(sort_work, scan_work, out_work_units)) return false;
    return true;
}

bool raster_fill_scanline_cache_create(const svg_shape_document *document,
                                       raster_fill_scanline_cache *out_cache,
                                       svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
    if (out_cache == NULL) return false;
    *out_cache = (raster_fill_scanline_cache){0};
    if (document == NULL || (document->shape_count != 0U &&
        document->shape_count > SIZE_MAX / sizeof(*out_cache->eligible_shapes)))
        return false;
    if (document->shape_count == 0U) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    bool *eligible = calloc(document->shape_count, sizeof(*eligible));
    if (eligible == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    size_t max_edge_count = 0U;
    for (size_t shape = 0U; shape < document->shape_count; shape++) {
        size_t edge_count = document->shape_edge_count[shape];
        if (edge_count > RASTER_FILL_SCANLINE_MAX_EDGES ||
            !shape_is_uniform_filled(document, shape)) continue;
        eligible[shape] = true;
        if (edge_count > max_edge_count) max_edge_count = edge_count;
    }
    out_cache->eligible_shapes = eligible;
    out_cache->shape_count = document->shape_count;
    if (max_edge_count == 0U) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    if ((size_t)document->width >
        RASTER_FILL_SCANLINE_PIXEL_RUN_LIMIT / sizeof(*out_cache->pixel_runs)) {
        memset(eligible, 0, document->shape_count * sizeof(*eligible));
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    size_t interval_stride, interval_count, crossing_bytes, interval_bytes;
    if (!checked_add_size(max_edge_count, 1U, &interval_stride) ||
        !checked_mul_size(interval_stride, RASTER_FILL_SCANLINE_SAMPLE_ROWS,
                          &interval_count) ||
        max_edge_count > SIZE_MAX / sizeof(*out_cache->crossings) ||
        interval_count > SIZE_MAX / sizeof(*out_cache->intervals)) {
        raster_fill_scanline_cache_destroy(out_cache);
        return false;
    }
    crossing_bytes = max_edge_count * sizeof(*out_cache->crossings);
    interval_bytes = interval_count * sizeof(*out_cache->intervals);
    out_cache->crossings = malloc(crossing_bytes);
    out_cache->intervals = malloc(interval_bytes);
    out_cache->pixel_run_capacity = document->width;
    out_cache->pixel_runs = malloc((size_t)document->width *
                                   sizeof(*out_cache->pixel_runs));
    if (out_cache->crossings == NULL || out_cache->intervals == NULL ||
        out_cache->pixel_runs == NULL) {
        raster_fill_scanline_cache_destroy(out_cache);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    out_cache->max_edge_count = max_edge_count;
    out_cache->interval_stride = interval_stride;
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
    return true;
}

void raster_fill_scanline_cache_destroy(raster_fill_scanline_cache *cache)
{
    if (cache == NULL) return;
    free(cache->eligible_shapes);
    free(cache->crossings);
    free(cache->intervals);
    free(cache->pixel_runs);
    *cache = (raster_fill_scanline_cache){0};
}

bool raster_fill_scanline_cache_is_eligible(
    const raster_fill_scanline_cache *cache, size_t shape)
{
    return cache != NULL && cache->eligible_shapes != NULL &&
           shape < cache->shape_count && cache->eligible_shapes[shape];
}

const uint8_t *raster_fill_scanline_cache_color(
    const svg_shape_document *document, size_t shape)
{
    if (document == NULL || shape >= document->shape_count ||
        document->shape_edge_start == NULL || document->colors == NULL ||
        document->shape_edge_start[shape] >= document->edge_count) return NULL;
    return document->colors + document->shape_edge_start[shape] * 4U;
}

bool raster_fill_scanline_cache_build_row(
    raster_fill_scanline_cache *cache, const svg_shape_document *document,
    size_t shape, uint32_t pixel_y, double scale_y, double offset_y,
    const size_t *shape_offsets, const uint32_t *active_edges, size_t stride,
    size_t *out_edge_visits, size_t *out_work_units)
{
    if (out_edge_visits != NULL) *out_edge_visits = 0U;
    if (out_work_units != NULL) *out_work_units = 0U;
    if (!raster_fill_scanline_cache_is_eligible(cache, shape) ||
        document == NULL || shape_offsets == NULL || stride <= shape ||
        !isfinite(scale_y) || scale_y <= 0.0 || !isfinite(offset_y) ||
        cache->crossings == NULL || cache->intervals == NULL) return false;
    size_t edge_visits = 0U;
    size_t work_units = 0U;
    for (size_t sample = 0U; sample < RASTER_FILL_SCANLINE_SAMPLE_ROWS;
         sample++) {
        size_t base = sample * stride + shape;
        size_t first = shape_offsets[base];
        size_t end = shape_offsets[base + 1U];
        if (end < first || end - first > cache->max_edge_count) return false;
        size_t count = 0U, visits = 0U, work = 0U;
        double device_y = (double)pixel_y + sample_y_offsets[sample];
        double user_y = document->view_y + (device_y - offset_y) / scale_y;
        const uint32_t *edges = end == first || active_edges == NULL ? NULL :
                                active_edges + first;
        if (!build_intervals(document, shape, user_y, edges, end - first,
                cache->crossings, cache->max_edge_count,
                cache->intervals + sample * cache->interval_stride,
                cache->interval_stride, &count, &visits, &work) ||
            !checked_add_size(edge_visits, visits, &edge_visits) ||
            !checked_add_size(work_units, work, &work_units)) return false;
        cache->interval_counts[sample] = count;
    }
    if (out_edge_visits != NULL) *out_edge_visits = edge_visits;
    if (out_work_units != NULL) *out_work_units = work_units;
    return true;
}

bool raster_fill_scanline_cache_build_pixel_runs(
    raster_fill_scanline_cache *cache, const svg_shape_document *document,
    const raster_pixel_bounds *pixel_bounds, uint32_t pixel_y,
    const raster_boundary_mask *boundary, double scale_x, double scale_y,
    double offset_x, double offset_y, size_t *out_work_units)
{
    if (out_work_units != NULL) *out_work_units = 0U;
    if (cache == NULL || document == NULL || pixel_bounds == NULL ||
        boundary == NULL || boundary->bits == NULL || !pixel_bounds->visible ||
        pixel_y < pixel_bounds->y_first || pixel_y > pixel_bounds->y_last ||
        !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        !isfinite(offset_x) || !isfinite(offset_y) ||
        cache->pixel_runs == NULL) return false;
    cache->pixel_run_count = 0U;
    bool have_run = false;
    bool run_center_only = false;
    size_t run_width = 0U;
    uint32_t run_first = 0U;
    for (uint32_t x = pixel_bounds->x_first; ; x++) {
        size_t pixel = (size_t)pixel_y * document->width + x;
        bool center_only = pixel_is_fully_in_view(document, x, pixel_y,
                scale_x, scale_y, offset_x, offset_y) &&
            !raster_boundary_mask_test(boundary, pixel);
        if (!have_run || center_only != run_center_only) {
            if (have_run) {
                if (cache->pixel_run_count >= cache->pixel_run_capacity) return false;
                cache->pixel_runs[cache->pixel_run_count++] =
                    (raster_fill_pixel_run){run_first, x, run_center_only};
            }
            run_first = x;
            run_center_only = center_only;
            have_run = true;
        }
        run_width++;
        if (x == pixel_bounds->x_last) break;
    }
    if (have_run) {
        uint32_t end_x = pixel_bounds->x_last + 1U;
        if (cache->pixel_run_count >= cache->pixel_run_capacity) return false;
        cache->pixel_runs[cache->pixel_run_count++] =
            (raster_fill_pixel_run){run_first, end_x, run_center_only};
    }
    if (out_work_units != NULL) *out_work_units = run_width;
    return true;
}

const raster_fill_pixel_run *raster_fill_scanline_cache_pixel_runs(
    const raster_fill_scanline_cache *cache, size_t *out_run_count)
{
    if (out_run_count != NULL) *out_run_count = 0U;
    if (cache == NULL || cache->pixel_runs == NULL) return NULL;
    if (out_run_count != NULL) *out_run_count = cache->pixel_run_count;
    return cache->pixel_runs;
}

static size_t first_sample_x_at_least(const svg_shape_document *document,
                                      const raster_pixel_bounds *pixel_bounds,
                                      double scale_x, double offset_x,
                                      double sample_offset, double target,
                                      size_t *comparisons)
{
    size_t low = pixel_bounds->x_first;
    size_t high = (size_t)pixel_bounds->x_last + 1U;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        double device_x = (double)middle + sample_offset;
        double user_x = document->view_x + (device_x - offset_x) / scale_x;
        (*comparisons)++;
        if (user_x < target) low = middle + 1U;
        else high = middle;
    }
    return low;
}

bool raster_fill_scanline_interval_pixel_range(
    const svg_shape_document *document, const raster_pixel_bounds *pixel_bounds,
    double scale_x, double offset_x, double sample_offset,
    const raster_fill_scanline_interval *interval,
    size_t *out_first_x, size_t *out_end_x, size_t *out_comparisons)
{
    if (out_first_x != NULL) *out_first_x = 0U;
    if (out_end_x != NULL) *out_end_x = 0U;
    if (out_comparisons != NULL) *out_comparisons = 0U;
    if (document == NULL || pixel_bounds == NULL || interval == NULL ||
        out_first_x == NULL || out_end_x == NULL ||
        !pixel_bounds->visible || !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(offset_x) || !isfinite(sample_offset) ||
        isnan(interval->left) || isnan(interval->right) ||
        interval->right < interval->left) return false;
    size_t comparisons = 0U;
    size_t first = isinf(interval->left) && interval->left < 0.0 ?
        pixel_bounds->x_first : first_sample_x_at_least(document, pixel_bounds,
            scale_x, offset_x, sample_offset, interval->left, &comparisons);
    size_t end = isinf(interval->right) && interval->right > 0.0 ?
        (size_t)pixel_bounds->x_last + 1U :
        first_sample_x_at_least(document, pixel_bounds, scale_x, offset_x,
            sample_offset, interval->right, &comparisons);
    if (end < first) return false;
    *out_first_x = first;
    *out_end_x = end;
    if (out_comparisons != NULL) *out_comparisons = comparisons;
    return true;
}

bool raster_fill_scanline_cache_contains(
    const raster_fill_scanline_cache *cache, size_t sample_row, double x,
    size_t *out_comparisons)
{
    if (out_comparisons != NULL) *out_comparisons = 0U;
    if (cache == NULL || cache->intervals == NULL ||
        sample_row >= RASTER_FILL_SCANLINE_SAMPLE_ROWS || isnan(x)) return false;
    const raster_fill_scanline_interval *intervals =
        cache->intervals + sample_row * cache->interval_stride;
    size_t low = 0U;
    size_t high = cache->interval_counts[sample_row];
    size_t comparisons = 1U;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        comparisons++;
        if (intervals[middle].right <= x) low = middle + 1U;
        else high = middle;
    }
    if (out_comparisons != NULL) *out_comparisons = comparisons;
    return low < cache->interval_counts[sample_row] &&
           intervals[low].left <= x && x < intervals[low].right;
}

#include "shape_scanline.h"

#include <math.h>
#include <stdlib.h>

#define RASTER_SCANLINE_MAX_TREE_DEPTH 64U

static const double sample_y_offsets[RASTER_SCANLINE_VALUES_PER_ROW] = {
    0.125, 0.375, 0.5, 0.625, 0.875
};

static double user_scanline_y(const svg_shape_document *doc, size_t slot,
                              double scale_y, double offset_y)
{
    size_t pixel_y = slot / RASTER_SCANLINE_VALUES_PER_ROW;
    size_t sample = slot % RASTER_SCANLINE_VALUES_PER_ROW;
    double device_y = (double)pixel_y + sample_y_offsets[sample];
    return doc->view_y + (device_y - offset_y) / scale_y;
}

static size_t first_scanline_at_or_above(const svg_shape_document *doc,
                                         size_t count, double target,
                                         double scale_y, double offset_y)
{
    size_t low = 0U;
    size_t high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        double y = user_scanline_y(doc, middle, scale_y, offset_y);
        if (y < target) low = middle + 1U;
        else high = middle;
    }
    return low;
}

static int compare_events(const void *left_ptr, const void *right_ptr)
{
    const raster_scanline_event *left = left_ptr;
    const raster_scanline_event *right = right_ptr;
    if (left->slot < right->slot) return -1;
    if (left->slot > right->slot) return 1;
    if (left->edge < right->edge) return -1;
    if (left->edge > right->edge) return 1;
    if (left->add == right->add) return 0;
    return left->add ? 1 : -1;
}

static int compare_shape_events(const void *left_ptr, const void *right_ptr)
{
    const raster_shape_row_event *left = left_ptr;
    const raster_shape_row_event *right = right_ptr;
    if (left->row < right->row) return -1;
    if (left->row > right->row) return 1;
    if (left->add != right->add) return left->add ? 1 : -1;
    if (left->shape < right->shape) return -1;
    if (left->shape > right->shape) return 1;
    return 0;
}

static int32_t node_height(const raster_scanline_node *nodes, int32_t node)
{
    return node < 0 ? 0 : nodes[(size_t)node].height;
}

static void update_height(raster_scanline_node *nodes, int32_t node)
{
    int32_t left = nodes[(size_t)node].left;
    int32_t right = nodes[(size_t)node].right;
    int32_t left_height = node_height(nodes, left);
    int32_t right_height = node_height(nodes, right);
    nodes[(size_t)node].height = 1 + (left_height > right_height
                                        ? left_height : right_height);
}

static int32_t rotate_left(raster_scanline_node *nodes, int32_t root)
{
    int32_t pivot = nodes[(size_t)root].right;
    nodes[(size_t)root].right = nodes[(size_t)pivot].left;
    nodes[(size_t)pivot].left = root;
    update_height(nodes, root);
    update_height(nodes, pivot);
    return pivot;
}

static int32_t rotate_right(raster_scanline_node *nodes, int32_t root)
{
    int32_t pivot = nodes[(size_t)root].left;
    nodes[(size_t)root].left = nodes[(size_t)pivot].right;
    nodes[(size_t)pivot].right = root;
    update_height(nodes, root);
    update_height(nodes, pivot);
    return pivot;
}

static int32_t rebalance(raster_scanline_node *nodes, int32_t root)
{
    if (root < 0) return root;
    update_height(nodes, root);
    int32_t balance = node_height(nodes, nodes[(size_t)root].left) -
                      node_height(nodes, nodes[(size_t)root].right);
    if (balance > 1) {
        int32_t left = nodes[(size_t)root].left;
        if (node_height(nodes, nodes[(size_t)left].left) <
            node_height(nodes, nodes[(size_t)left].right))
            nodes[(size_t)root].left = rotate_left(nodes, left);
        return rotate_right(nodes, root);
    }
    if (balance < -1) {
        int32_t right = nodes[(size_t)root].right;
        if (node_height(nodes, nodes[(size_t)right].right) <
            node_height(nodes, nodes[(size_t)right].left))
            nodes[(size_t)root].right = rotate_right(nodes, right);
        return rotate_left(nodes, root);
    }
    return root;
}

static int32_t insert_node(raster_scanline_node *nodes, int32_t root,
                           int32_t key, size_t depth, bool *ok)
{
    if (depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) {
        *ok = false;
        return root;
    }
    if (root < 0) return key;
    if (key < root) {
        nodes[(size_t)root].left = insert_node(nodes, nodes[(size_t)root].left,
                                               key, depth + 1U, ok);
    } else if (key > root) {
        nodes[(size_t)root].right = insert_node(nodes, nodes[(size_t)root].right,
                                                key, depth + 1U, ok);
    } else {
        *ok = false;
        return root;
    }
    return *ok ? rebalance(nodes, root) : root;
}

static int32_t remove_node(raster_scanline_node *nodes, int32_t root,
                           int32_t key, size_t depth, bool *ok)
{
    if (root < 0 || depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) {
        *ok = false;
        return root;
    }
    if (key < root) {
        nodes[(size_t)root].left = remove_node(nodes, nodes[(size_t)root].left,
                                               key, depth + 1U, ok);
    } else if (key > root) {
        nodes[(size_t)root].right = remove_node(nodes, nodes[(size_t)root].right,
                                                key, depth + 1U, ok);
    } else {
        int32_t left = nodes[(size_t)root].left;
        int32_t right = nodes[(size_t)root].right;
        if (left < 0) return right;
        if (right < 0) return left;
        if (node_height(nodes, left) > node_height(nodes, right)) {
            root = rotate_right(nodes, root);
            nodes[(size_t)root].right = remove_node(
                nodes, nodes[(size_t)root].right, key, depth + 1U, ok);
        } else {
            root = rotate_left(nodes, root);
            nodes[(size_t)root].left = remove_node(
                nodes, nodes[(size_t)root].left, key, depth + 1U, ok);
        }
    }
    return *ok ? rebalance(nodes, root) : root;
}

static bool append_tree_in_order(const raster_scanline_node *nodes, int32_t root,
                                 uint32_t *destination, size_t capacity,
                                 size_t *cursor)
{
    int32_t stack[RASTER_SCANLINE_MAX_TREE_DEPTH];
    size_t depth = 0U;
    int32_t current = root;
    while (current >= 0 || depth != 0U) {
        while (current >= 0) {
            if (depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) return false;
            stack[depth++] = current;
            current = nodes[(size_t)current].left;
        }
        current = stack[--depth];
        if (*cursor >= capacity) return false;
        destination[*cursor] = (uint32_t)current;
        (*cursor)++;
        current = nodes[(size_t)current].right;
    }
    return true;
}

bool raster_scanline_index_create(const svg_shape_document *doc,
                                  const raster_shape_bounds_set *bounds,
                                  double scale_y, double offset_y,
                                  raster_scanline_index *out,
                                  svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0};
    if (out == NULL) return false;
    *out = (raster_scanline_index){0};
    if (doc == NULL || bounds == NULL || bounds->shape_count != doc->shape_count ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        (size_t)doc->height > SIZE_MAX / RASTER_SCANLINE_VALUES_PER_ROW ||
        doc->edge_count > SIZE_MAX / 2U || doc->shape_count > SIZE_MAX / 2U ||
        doc->edge_count > INT32_MAX || doc->shape_count > INT32_MAX ||
        doc->edge_count > SIZE_MAX / sizeof(*out->nodes) ||
        doc->shape_count > SIZE_MAX / sizeof(*out->roots)) return false;
    size_t max_events = doc->edge_count * 2U;
    size_t max_shape_events = doc->shape_count * 2U;
    size_t scanline_count = (size_t)doc->height * RASTER_SCANLINE_VALUES_PER_ROW;
    raster_scanline_event *events = max_events == 0U ? NULL :
        malloc(max_events * sizeof(*events));
    raster_scanline_node *nodes = doc->edge_count == 0U ? NULL :
        malloc(doc->edge_count * sizeof(*nodes));
    int32_t *roots = doc->shape_count == 0U ? NULL :
        malloc(doc->shape_count * sizeof(*roots));
    raster_shape_row_event *shape_events = max_shape_events == 0U ? NULL :
        malloc(max_shape_events * sizeof(*shape_events));
    raster_scanline_node *shape_nodes = doc->shape_count == 0U ? NULL :
        malloc(doc->shape_count * sizeof(*shape_nodes));
    if ((max_events != 0U && events == NULL) ||
        (doc->edge_count != 0U && nodes == NULL) ||
        (doc->shape_count != 0U && (roots == NULL || shape_nodes == NULL)) ||
        (max_shape_events != 0U && shape_events == NULL)) {
        free(events); free(nodes); free(roots); free(shape_events); free(shape_nodes);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0};
        return false;
    }
    size_t shape_event_count = 0U;
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        roots[shape] = -1;
        const raster_pixel_bounds *box = &bounds->shapes[shape].pixels;
        if (!box->visible) continue;
        shape_events[shape_event_count++] = (raster_shape_row_event){
            box->y_first, (uint32_t)shape, true};
        shape_events[shape_event_count++] = (raster_shape_row_event){
            box->y_last + 1U, (uint32_t)shape, false};
    }
    size_t event_count = 0U;
    for (size_t edge_index = 0U; edge_index < doc->edge_count; edge_index++) {
        size_t shape = doc->shape_ids[edge_index];
        if (shape >= doc->shape_count) continue;
        geom_edge edge = doc->edges[edge_index];
        if (!doc->shape_filled[shape] || isnan(edge.a.y) || isnan(edge.b.y) ||
            edge.a.y == edge.b.y) continue;
        double low_y = fmin(edge.a.y, edge.b.y);
        double high_y = fmax(edge.a.y, edge.b.y);
        size_t first = first_scanline_at_or_above(doc, scanline_count, low_y,
                                                   scale_y, offset_y);
        size_t end = first_scanline_at_or_above(doc, scanline_count, high_y,
                                                 scale_y, offset_y);
        if (first >= end || first >= scanline_count) continue;
        if (end > scanline_count) end = scanline_count;
        events[event_count++] = (raster_scanline_event){first,
            (uint32_t)edge_index, true};
        events[event_count++] = (raster_scanline_event){end,
            (uint32_t)edge_index, false};
    }
    if (event_count > 1U) qsort(events, event_count, sizeof(*events), compare_events);
    if (shape_event_count > 1U)
        qsort(shape_events, shape_event_count, sizeof(*shape_events), compare_shape_events);
    out->document = doc;
    out->events = events;
    out->nodes = nodes;
    out->roots = roots;
    out->shape_events = shape_events;
    out->shape_nodes = shape_nodes;
    out->shape_root = -1;
    out->event_count = event_count;
    out->shape_event_count = shape_event_count;
    out->shape_count = doc->shape_count;
    out->edge_count = doc->edge_count;
    out->scanline_count = scanline_count;
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0};
    return true;
}

void raster_scanline_index_reset(raster_scanline_index *index)
{
    if (index == NULL) return;
    index->event_cursor = 0U;
    index->shape_event_cursor = 0U;
    index->listed_edge_count = 0U;
    index->shape_root = -1;
    for (size_t shape = 0U; shape < index->shape_count; shape++)
        index->roots[shape] = -1;
}

void raster_scanline_index_destroy(raster_scanline_index *index)
{
    if (index == NULL) return;
    free(index->events);
    free(index->nodes);
    free(index->roots);
    free(index->shape_events);
    free(index->shape_nodes);
    *index = (raster_scanline_index){0};
}

bool raster_scanline_index_build_row(raster_scanline_index *index,
                                     uint32_t pixel_y,
                                     size_t *shape_offsets,
                                     uint32_t *active_edges,
                                     size_t active_edge_capacity,
                                     uint32_t *active_shapes,
                                     size_t active_shape_capacity,
                                     size_t *active_shape_count)
{
    if (index == NULL || shape_offsets == NULL || active_shape_count == NULL ||
        (index->edge_count != 0U && active_edges == NULL) ||
        (index->shape_count != 0U && active_shapes == NULL) ||
        (size_t)pixel_y > SIZE_MAX / RASTER_SCANLINE_VALUES_PER_ROW) return false;
    *active_shape_count = 0U;
    while (index->shape_event_cursor < index->shape_event_count &&
           index->shape_events[index->shape_event_cursor].row <= pixel_y) {
        raster_shape_row_event event = index->shape_events[index->shape_event_cursor++];
        int32_t shape = (int32_t)event.shape;
        bool ok = true;
        if (event.add) {
            index->shape_nodes[event.shape] = (raster_scanline_node){-1, -1, 1};
            index->shape_root = insert_node(index->shape_nodes, index->shape_root,
                                            shape, 0U, &ok);
        } else {
            index->shape_root = remove_node(index->shape_nodes, index->shape_root,
                                            shape, 0U, &ok);
        }
        if (!ok) return false;
    }
    if (!append_tree_in_order(index->shape_nodes, index->shape_root, active_shapes,
                              active_shape_capacity, active_shape_count)) return false;
    size_t stride = index->shape_count + 1U;
    size_t write_cursor = 0U;
    for (size_t sample = 0U; sample < RASTER_SCANLINE_VALUES_PER_ROW; sample++) {
        size_t slot = (size_t)pixel_y * RASTER_SCANLINE_VALUES_PER_ROW + sample;
        while (index->event_cursor < index->event_count &&
               index->events[index->event_cursor].slot <= slot) {
            raster_scanline_event event = index->events[index->event_cursor++];
            size_t shape = index->document->shape_ids[event.edge];
            bool ok = true;
            if (event.add) {
                raster_scanline_node *node = &index->nodes[event.edge];
                *node = (raster_scanline_node){-1, -1, 1};
                index->roots[shape] = insert_node(index->nodes, index->roots[shape],
                    (int32_t)event.edge, 0U, &ok);
            } else {
                index->roots[shape] = remove_node(index->nodes, index->roots[shape],
                    (int32_t)event.edge, 0U, &ok);
            }
            if (!ok) return false;
        }
        size_t row_offset = sample * stride;
        for (size_t active = 0U; active < *active_shape_count; active++) {
            size_t shape = active_shapes[active];
            shape_offsets[row_offset + shape] = write_cursor;
            if (!append_tree_in_order(index->nodes, index->roots[shape], active_edges,
                                      active_edge_capacity, &write_cursor)) return false;
            shape_offsets[row_offset + shape + 1U] = write_cursor;
        }
    }
    index->listed_edge_count += write_cursor;
    return true;
}

#include "shape_bounds.h"
#include "../svg/clip/clip.h"

#include <float.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define RASTER_BOUNDARY_WORK_LIMIT 200000000U

typedef struct geometry_bounds {
    double left;
    double top;
    double right;
    double bottom;
    bool present;
    bool invalid;
} geometry_bounds;

static bool checked_add_size(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool checked_mul_size(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static void bounds_include(geometry_bounds *bounds, geom_point point)
{
    if (!isfinite(point.x) || !isfinite(point.y)) {
        bounds->invalid = true;
        return;
    }
    if (!bounds->present) {
        bounds->left = bounds->right = point.x;
        bounds->top = bounds->bottom = point.y;
        bounds->present = true;
        return;
    }
    bounds->left = fmin(bounds->left, point.x);
    bounds->right = fmax(bounds->right, point.x);
    bounds->top = fmin(bounds->top, point.y);
    bounds->bottom = fmax(bounds->bottom, point.y);
}

static bool pixel_range(double low, double high, uint32_t extent,
                        uint32_t *first, uint32_t *last)
{
    if (extent == 0U || !isfinite(low) || !isfinite(high) || high < low) return false;
    /* Include every 4x4 sample footprint plus one pixel for roundoff margin. */
    double first_value = ceil(low - 0.875) - 1.0;
    double last_value = floor(high - 0.125) + 1.0;
    if (last_value < 0.0 || first_value >= (double)extent) return false;
    if (first_value <= 0.0) *first = 0U;
    else *first = (uint32_t)first_value;
    if (last_value >= (double)extent) *last = extent - 1U;
    else *last = (uint32_t)last_value;
    return *first <= *last;
}

static void full_tile_bounds(const svg_shape_document *doc,
                             raster_shape_bounds *bounds)
{
    bounds->device_left = 0.0;
    bounds->device_top = 0.0;
    bounds->device_right = (double)doc->width;
    bounds->device_bottom = (double)doc->height;
    bounds->pixels = (raster_pixel_bounds){0U, doc->width - 1U,
                                           0U, doc->height - 1U, true};
}

static bool map_user_box(const svg_shape_document *doc,
                         double scale_x, double scale_y,
                         double offset_x, double offset_y,
                         geometry_bounds user, raster_shape_bounds *out)
{
    if (!user.present && !user.invalid) {
        out->pixels = (raster_pixel_bounds){0U, 0U, 0U, 0U, false};
        return true;
    }
    if (user.invalid) {
        full_tile_bounds(doc, out);
        return true;
    }
    double left = offset_x + (user.left - doc->view_x) * scale_x;
    double right = offset_x + (user.right - doc->view_x) * scale_x;
    double top = offset_y + (user.top - doc->view_y) * scale_y;
    double bottom = offset_y + (user.bottom - doc->view_y) * scale_y;
    if (!isfinite(left) || !isfinite(right) || !isfinite(top) || !isfinite(bottom)) {
        full_tile_bounds(doc, out);
        return true;
    }
    double margin_x = fmax(1.0, fmax(fabs(left), fabs(right))) * DBL_EPSILON * 8.0;
    double margin_y = fmax(1.0, fmax(fabs(top), fabs(bottom))) * DBL_EPSILON * 8.0;
    left -= margin_x;
    right += margin_x;
    top -= margin_y;
    bottom += margin_y;
    out->device_left = left;
    out->device_top = top;
    out->device_right = right;
    out->device_bottom = bottom;
    out->pixels.visible = pixel_range(left, right, doc->width,
                                      &out->pixels.x_first, &out->pixels.x_last) &&
                          pixel_range(top, bottom, doc->height,
                                      &out->pixels.y_first, &out->pixels.y_last);
    return true;
}

static bool stroke_padding(const svg_shape_document *doc, size_t shape,
                           double *pad_x, double *pad_y)
{
    const svg_shape_stroke *stroke = &doc->strokes[shape];
    *pad_x = 0.0;
    *pad_y = 0.0;
    if (stroke->rgba[3] == 0U || stroke->width <= 0.0) return true;
    geom_affine inverse = doc->shape_stroke_inverse[shape];
    double determinant = inverse.a * inverse.d - inverse.b * inverse.c;
    double forward_a = inverse.d / determinant;
    double forward_b = -inverse.c / determinant;
    double forward_c = -inverse.b / determinant;
    double forward_d = inverse.a / determinant;
    double radius = stroke->width * 0.5;
    double join_factor = stroke->join == SVG_SHAPE_JOIN_MITER ? stroke->miter_limit : 1.0;
    double cap_factor = !doc->shape_stroke_closed[shape] &&
                        stroke->cap == SVG_SHAPE_CAP_SQUARE ? sqrt(2.0) : 1.0;
    double extent = radius * fmax(join_factor, cap_factor);
    *pad_x = extent * hypot(forward_a, forward_b);
    *pad_y = extent * hypot(forward_c, forward_d);
    return isfinite(*pad_x) && isfinite(*pad_y);
}

bool raster_shape_bounds_build(const svg_shape_document *doc,
                               double scale_x, double scale_y,
                               double offset_x, double offset_y,
                               raster_shape_bounds_set *out,
                               svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0};
    if (out == NULL) return false;
    *out = (raster_shape_bounds_set){0};
    if (doc == NULL || doc->width == 0U || doc->height == 0U ||
        doc->shape_count > SIZE_MAX / sizeof(*out->shapes)) return false;
    if (doc->shape_count == 0U) return true;
    geometry_bounds *fills = calloc(doc->shape_count, sizeof(*fills));
    geometry_bounds *strokes = calloc(doc->shape_count, sizeof(*strokes));
    raster_shape_bounds *shapes = calloc(doc->shape_count, sizeof(*shapes));
    if (fills == NULL || strokes == NULL || shapes == NULL) {
        free(fills); free(strokes); free(shapes);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0};
        return false;
    }
    for (size_t i = 0U; i < doc->edge_count; i++) {
        size_t shape = doc->shape_ids[i];
        if (shape >= doc->shape_count) continue;
        if (doc->shape_filled[shape]) {
            bounds_include(&fills[shape], doc->edges[i].a);
            bounds_include(&fills[shape], doc->edges[i].b);
        }
    }
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        size_t first = doc->shape_edge_start[shape];
        size_t count = doc->shape_edge_count[shape];
        bool stroked = doc->strokes[shape].rgba[3] != 0U &&
                       doc->strokes[shape].width > 0.0 && count != 0U;
        if (stroked) {
            double pad_x, pad_y;
            for (size_t edge = 0U; edge < count; edge++) {
                bounds_include(&strokes[shape], doc->edges[first + edge].a);
                bounds_include(&strokes[shape], doc->edges[first + edge].b);
            }
            if (!stroke_padding(doc, shape, &pad_x, &pad_y)) {
                strokes[shape].invalid = true;
            } else if (strokes[shape].present && !strokes[shape].invalid) {
                strokes[shape].left -= pad_x;
                strokes[shape].right += pad_x;
                strokes[shape].top -= pad_y;
                strokes[shape].bottom += pad_y;
            }
        }
        geometry_bounds combined = fills[shape];
        if (strokes[shape].present || strokes[shape].invalid) {
            if (!combined.present) combined = strokes[shape];
            else {
                combined.left = fmin(combined.left, strokes[shape].left);
                combined.right = fmax(combined.right, strokes[shape].right);
                combined.top = fmin(combined.top, strokes[shape].top);
                combined.bottom = fmax(combined.bottom, strokes[shape].bottom);
                combined.invalid |= strokes[shape].invalid;
            }
        }
        if (!map_user_box(doc, scale_x, scale_y, offset_x, offset_y,
                          combined, &shapes[shape])) {
            free(fills); free(strokes); free(shapes);
            return false;
        }
        if (shapes[shape].pixels.visible) {
            size_t width = (size_t)shapes[shape].pixels.x_last -
                           shapes[shape].pixels.x_first + 1U;
            size_t height = (size_t)shapes[shape].pixels.y_last -
                            shapes[shape].pixels.y_first + 1U;
            size_t area;
            if (!checked_mul_size(width, height, &area) ||
                !checked_add_size(out->pixel_count, area, &out->pixel_count)) {
                free(fills); free(strokes); free(shapes);
                return false;
            }
        }
    }
    free(fills);
    free(strokes);
    out->shapes = shapes;
    out->shape_count = doc->shape_count;
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0};
    return true;
}

void raster_shape_bounds_destroy(raster_shape_bounds_set *bounds)
{
    if (bounds == NULL) return;
    free(bounds->shapes);
    *bounds = (raster_shape_bounds_set){0};
}

static bool edge_stroke_radius(const svg_shape_document *doc, size_t shape,
                               bool include_miter, double *radius)
{
    *radius = 0.0;
    const svg_shape_stroke *stroke = &doc->strokes[shape];
    if (stroke->rgba[3] == 0U || stroke->width <= 0.0) return true;
    geom_affine inverse = doc->shape_stroke_inverse[shape];
    double determinant = inverse.a * inverse.d - inverse.b * inverse.c;
    double a = inverse.d / determinant;
    double b = -inverse.b / determinant;
    double c = -inverse.c / determinant;
    double d = inverse.a / determinant;
    double scale_bound = sqrt(a*a + b*b + c*c + d*d);
    double join_bound = include_miter && stroke->join == SVG_SHAPE_JOIN_MITER ?
                        stroke->miter_limit : 1.0;
    double cap_bound = !doc->shape_stroke_closed[shape] &&
                       stroke->cap == SVG_SHAPE_CAP_SQUARE ? sqrt(2.0) : 1.0;
    *radius = stroke->width * 0.5 * scale_bound * fmax(join_bound, cap_bound);
    return isfinite(*radius);
}

static bool boundary_pixel_range(double low, double high, uint32_t extent,
                                 uint32_t *first, uint32_t *last);

static bool point_boundary_bounds(const svg_shape_document *doc,
                                  geom_point point, double scale_x,
                                  double scale_y, double offset_x,
                                  double offset_y, double radius,
                                  raster_pixel_bounds *out)
{
    double x = offset_x + (point.x - doc->view_x) * scale_x;
    double y = offset_y + (point.y - doc->view_y) * scale_y;
    double padding_x = radius * scale_x;
    double padding_y = radius * scale_y;
    double epsilon = fmax(1.0, fmax(fabs(x), fabs(y))) * DBL_EPSILON * 8.0;
    uint32_t x_first, x_last, y_first, y_last;
    bool valid = isfinite(x) && isfinite(y) && isfinite(padding_x) &&
                 isfinite(padding_y) && isfinite(epsilon);
    if (!valid) return false;
    bool x_visible = boundary_pixel_range(x - padding_x - epsilon,
        x + padding_x + epsilon, doc->width, &x_first, &x_last);
    bool y_visible = boundary_pixel_range(y - padding_y - epsilon,
        y + padding_y + epsilon, doc->height, &y_first, &y_last);
    if (x_visible && y_visible)
        *out = (raster_pixel_bounds){x_first, x_last, y_first, y_last, true};
    else
        *out = (raster_pixel_bounds){0};
    return true;
}

static void mark_pixel(raster_boundary_mask *mask, size_t index);

static bool add_boundary_box_work(size_t *mark_work,
                                  const raster_pixel_bounds *box)
{
    if (!box->visible) return true;
    size_t width = (size_t)box->x_last - box->x_first + 1U;
    size_t height = (size_t)box->y_last - box->y_first + 1U;
    size_t area;
    return checked_mul_size(width, height, &area) &&
        checked_add_size(*mark_work, area, mark_work) &&
        *mark_work <= RASTER_BOUNDARY_WORK_LIMIT;
}

static void mark_boundary_box(raster_boundary_mask *mask,
                              const raster_pixel_bounds *box,
                              uint32_t width)
{
    if (!box->visible) return;
    for (uint32_t y = box->y_first; y <= box->y_last; ++y) {
        size_t row = (size_t)y * width;
        for (uint32_t x = box->x_first; x <= box->x_last; ++x)
            mark_pixel(mask, row + x);
    }
}

static bool boundary_pixel_range(double low, double high, uint32_t extent,
                                 uint32_t *first, uint32_t *last)
{
    if (extent == 0U || !isfinite(low) || !isfinite(high) || high < low) return false;
    double first_value = ceil(low - 1.0) - 1.0;
    double last_value = floor(high) + 1.0;
    if (last_value < 0.0 || first_value >= (double)extent) return false;
    *first = first_value <= 0.0 ? 0U : (uint32_t)first_value;
    *last = last_value >= (double)extent ? extent - 1U : (uint32_t)last_value;
    return *first <= *last;
}

static void mark_pixel(raster_boundary_mask *mask, size_t index)
{
    uint8_t bit = (uint8_t)(1U << (index & 7U));
    uint8_t *slot = &mask->bits[index >> 3U];
    if ((*slot & bit) == 0U) mask->marked_pixel_count++;
    *slot |= bit;
}

bool raster_shape_bounds_mark_boundaries(const svg_shape_document *doc,
                                         double scale_x, double scale_y,
                                         double offset_x,
                                         double offset_y,
                                         raster_boundary_mask *out,
                                         svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0};
    if (out == NULL) return false;
    *out = (raster_boundary_mask){0};
    if (doc == NULL || doc->width == 0U || doc->height == 0U ||
        (size_t)doc->width > SIZE_MAX / (size_t)doc->height) return false;
    size_t pixels = (size_t)doc->width * (size_t)doc->height;
    if (pixels > SIZE_MAX - 7U) return false;
    size_t byte_count = (pixels + 7U) / 8U;
    if (byte_count == 0U) return false;
    raster_pixel_bounds *edge_pixels = NULL;
    if (doc->edge_count > SIZE_MAX / sizeof(*edge_pixels)) return false;
    if (doc->edge_count != 0U) {
        edge_pixels = calloc(doc->edge_count, sizeof(*edge_pixels));
        if (edge_pixels == NULL) {
            if (diagnostic != NULL)
                *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0};
            return false;
        }
    }
    size_t mark_work = 0U;
    for (size_t i = 0U; i < doc->edge_count; i++) {
        size_t shape = doc->shape_ids[i];
        geom_edge edge = doc->edges[i];
        double radius;
        if (!edge_stroke_radius(doc, shape, false, &radius)) {
            edge_pixels[i] = (raster_pixel_bounds){0U, doc->width - 1U,
                                                   0U, doc->height - 1U, true};
        } else {
            double x1 = offset_x + (edge.a.x - doc->view_x) * scale_x;
            double x2 = offset_x + (edge.b.x - doc->view_x) * scale_x;
            double y1 = offset_y + (edge.a.y - doc->view_y) * scale_y;
            double y2 = offset_y + (edge.b.y - doc->view_y) * scale_y;
            double padding_x = radius * scale_x;
            double padding_y = radius * scale_y;
            double epsilon = fmax(1.0, fmax(fabs(x1), fmax(fabs(x2),
                                  fmax(fabs(y1), fabs(y2))))) * DBL_EPSILON * 8.0;
            uint32_t x_first, x_last, y_first, y_last;
            bool valid = isfinite(x1) && isfinite(x2) && isfinite(y1) &&
                         isfinite(y2) && isfinite(padding_x) &&
                         isfinite(padding_y) && isfinite(epsilon);
            bool x_visible = valid && boundary_pixel_range(fmin(x1, x2)-padding_x-epsilon,
                fmax(x1, x2)+padding_x+epsilon, doc->width, &x_first, &x_last);
            bool y_visible = valid && boundary_pixel_range(fmin(y1, y2)-padding_y-epsilon,
                fmax(y1, y2)+padding_y+epsilon, doc->height, &y_first, &y_last);
            if (!valid) {
                edge_pixels[i] = (raster_pixel_bounds){0U, doc->width - 1U,
                                                       0U, doc->height - 1U, true};
            } else if (x_visible && y_visible) {
                edge_pixels[i] = (raster_pixel_bounds){x_first, x_last, y_first,
                                                       y_last, true};
            }
        }
        if (!add_boundary_box_work(&mark_work, &edge_pixels[i])) {
            free(edge_pixels);
            return false;
        }
        const svg_shape_stroke *stroke = &doc->strokes[shape];
        if (stroke->rgba[3] != 0U && stroke->width > 0.0 &&
            stroke->join == SVG_SHAPE_JOIN_MITER) {
            double join_radius;
            if (!edge_stroke_radius(doc, shape, true, &join_radius)) {
                free(edge_pixels);
                return false;
            }
            const geom_point vertices[2] = {edge.a, edge.b};
            for (size_t endpoint = 0U; endpoint < 2U; ++endpoint) {
                raster_pixel_bounds join_box = {0};
                if (!point_boundary_bounds(doc, vertices[endpoint], scale_x,
                        scale_y, offset_x, offset_y, join_radius, &join_box) ||
                    !add_boundary_box_work(&mark_work, &join_box)) {
                    free(edge_pixels);
                    return false;
                }
            }
        }
    }
    uint8_t *bits = calloc(byte_count, 1U);
    if (bits == NULL) {
        free(edge_pixels);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0};
        return false;
    }
    out->bits = bits;
    out->bit_count = pixels;
    for (size_t i = 0U; i < doc->edge_count; i++) {
        mark_boundary_box(out, &edge_pixels[i], doc->width);
        size_t shape = doc->shape_ids[i];
        const svg_shape_stroke *stroke = &doc->strokes[shape];
        if (stroke->rgba[3] != 0U && stroke->width > 0.0 &&
            stroke->join == SVG_SHAPE_JOIN_MITER) {
            double join_radius;
            if (!edge_stroke_radius(doc, shape, true, &join_radius)) {
                raster_boundary_mask_destroy(out);
                free(edge_pixels);
                return false;
            }
            const geom_point vertices[2] = {doc->edges[i].a, doc->edges[i].b};
            for (size_t endpoint = 0U; endpoint < 2U; ++endpoint) {
                raster_pixel_bounds join_box = {0};
                if (!point_boundary_bounds(doc, vertices[endpoint], scale_x,
                        scale_y, offset_x, offset_y, join_radius, &join_box)) {
                    raster_boundary_mask_destroy(out);
                    free(edge_pixels);
                    return false;
                }
                mark_boundary_box(out, &join_box, doc->width);
            }
        }
    }
    out->mark_work = mark_work;
    free(edge_pixels);
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0};
    return true;
}

typedef struct clip_boundary_context {
    const svg_shape_document *document;
    raster_boundary_mask *boundary;
    double scale_x;
    double scale_y;
    double offset_x;
    double offset_y;
    size_t work;
    bool force_full_mask;
    bool mark;
} clip_boundary_context;

static bool clip_edge_pixel_bounds(const clip_boundary_context *context,
                                   geom_edge edge,
                                   raster_pixel_bounds *out)
{
    const svg_shape_document *doc = context->document;
    double x1 = context->offset_x + (edge.a.x - doc->view_x) * context->scale_x;
    double x2 = context->offset_x + (edge.b.x - doc->view_x) * context->scale_x;
    double y1 = context->offset_y + (edge.a.y - doc->view_y) * context->scale_y;
    double y2 = context->offset_y + (edge.b.y - doc->view_y) * context->scale_y;
    if (!isfinite(x1) || !isfinite(x2) || !isfinite(y1) || !isfinite(y2))
        return false;
    double epsilon = fmax(1.0, fmax(fabs(x1), fmax(fabs(x2),
                    fmax(fabs(y1), fabs(y2))))) * DBL_EPSILON * 8.0;
    uint32_t x_first, x_last, y_first, y_last;
    bool x_visible = boundary_pixel_range(fmin(x1, x2) - epsilon,
        fmax(x1, x2) + epsilon, doc->width, &x_first, &x_last);
    bool y_visible = boundary_pixel_range(fmin(y1, y2) - epsilon,
        fmax(y1, y2) + epsilon, doc->height, &y_first, &y_last);
    *out = x_visible && y_visible ?
        (raster_pixel_bounds){x_first, x_last, y_first, y_last, true} :
        (raster_pixel_bounds){0U, 0U, 0U, 0U, false};
    return true;
}

static bool add_clip_edge_work(clip_boundary_context *context, size_t amount)
{
    if (amount > RASTER_BOUNDARY_WORK_LIMIT - context->work) return false;
    context->work += amount;
    return true;
}

static bool preflight_clip_boundary_visits(const svg_shape_document *doc,
                                           raster_boundary_mask *boundary)
{
    size_t work = boundary->mark_work;
    size_t outer_shape_scans;
    if (!checked_mul_size(doc->shape_count, 3U, &outer_shape_scans) ||
        !checked_add_size(work, outer_shape_scans, &work)) {
        boundary->mark_work = SIZE_MAX;
        return false;
    }
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        if (doc->clips[shape] == NULL) continue;
        svg_clip_work_counts counts;
        size_t visit_units, both_passes, preflight_units, total_units;
        if (!svg_clip_boundary_work_counts(doc->clips[shape], &counts) ||
            !checked_add_size(counts.chain_elements, counts.child_shapes,
                              &visit_units) ||
            !checked_mul_size(visit_units, 2U, &both_passes) ||
            !checked_add_size(counts.chain_elements, both_passes,
                              &preflight_units) ||
            !checked_add_size(work, preflight_units, &total_units)) {
            boundary->mark_work = SIZE_MAX;
            return false;
        }
        work = total_units;
    }
    boundary->mark_work = work;
    return work <= RASTER_BOUNDARY_WORK_LIMIT;
}

static bool visit_clip_boundary_edge(void *opaque, geom_edge edge)
{
    clip_boundary_context *context = opaque;
    raster_pixel_bounds box;
    if (!context->mark) {
        if (!clip_edge_pixel_bounds(context, edge, &box)) {
            context->force_full_mask = true;
            return add_clip_edge_work(context, 2U);
        }
        size_t amount = 2U;
        if (box.visible) {
            size_t width = (size_t)box.x_last - box.x_first + 1U;
            size_t height = (size_t)box.y_last - box.y_first + 1U;
            size_t area;
            if (!checked_mul_size(width, height, &area) ||
                !checked_add_size(amount, area, &amount)) return false;
        }
        return add_clip_edge_work(context, amount);
    }
    if (context->force_full_mask ||
        !clip_edge_pixel_bounds(context, edge, &box)) {
        context->force_full_mask = true;
        return true;
    }
    if (!box.visible) return true;
    for (uint32_t y = box.y_first; y <= box.y_last; y++) {
        size_t row = (size_t)y * context->document->width;
        for (uint32_t x = box.x_first; x <= box.x_last; x++)
            mark_pixel(context->boundary, row + x);
    }
    return true;
}

static bool mark_full_boundary_mask(clip_boundary_context *context)
{
    size_t pixels = context->boundary->bit_count;
    if (!add_clip_edge_work(context, pixels)) return false;
    for (size_t pixel = 0U; pixel < pixels; pixel++)
        mark_pixel(context->boundary, pixel);
    return true;
}

bool raster_shape_bounds_mark_clip_boundaries(
    const svg_shape_document *doc, double scale_x, double scale_y,
    double offset_x,
    double offset_y, raster_boundary_mask *boundary)
{
    if (doc == NULL || boundary == NULL || boundary->bits == NULL ||
        !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        !isfinite(offset_x) || !isfinite(offset_y)) return false;
    if (!doc->has_clips || doc->clips == NULL) return true;
    if (!preflight_clip_boundary_visits(doc, boundary)) return false;
    clip_boundary_context context = {
        .document = doc,
        .boundary = boundary,
        .scale_x = scale_x,
        .scale_y = scale_y,
        .offset_x = offset_x,
        .offset_y = offset_y,
        .work = boundary->mark_work,
    };
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        if (doc->clips[shape] == NULL) continue;
        bool mapping_valid = true;
        if (!svg_clip_visit_boundary_edges(doc->clips[shape],
                visit_clip_boundary_edge, &context, &mapping_valid)) {
            boundary->mark_work = context.work;
            return false;
        }
        if (!mapping_valid) {
            context.force_full_mask = true;
            break;
        }
        if (context.force_full_mask) break;
    }
    if (context.force_full_mask) {
        if (!mark_full_boundary_mask(&context)) return false;
        boundary->mark_work = context.work;
        return true;
    }
    boundary->mark_work = context.work;
    context.mark = true;
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        if (doc->clips[shape] == NULL) continue;
        bool mapping_valid = true;
        if (!svg_clip_visit_boundary_edges(doc->clips[shape],
                visit_clip_boundary_edge, &context, &mapping_valid)) {
            boundary->mark_work = context.work;
            return false;
        }
        if (!mapping_valid || context.force_full_mask) {
            if (!mark_full_boundary_mask(&context)) return false;
            boundary->mark_work = context.work;
            return true;
        }
    }
    boundary->mark_work = context.work;
    return true;
}

void raster_boundary_mask_destroy(raster_boundary_mask *mask)
{
    if (mask == NULL) return;
    free(mask->bits);
    *mask = (raster_boundary_mask){0};
}

bool raster_boundary_mask_test(const raster_boundary_mask *mask, size_t pixel_index)
{
    if (mask == NULL || mask->bits == NULL || pixel_index >= mask->bit_count) return true;
    return (mask->bits[pixel_index >> 3U] & (uint8_t)(1U << (pixel_index & 7U))) != 0U;
}

#include "shape_render_preflight.h"

#include "shape_render_internal.h"
#include "../svg/clip/clip.h"
#include "../svg/paint/paint.h"

#include <math.h>
#include <stdint.h>

/*
 * Work budget of the native-resolution raster preflight, in work units.
 * budget(pixels) = min(CAP, BASE + max(0, pixels - RAMP_START) * PER_PIXEL).
 *   BASE         200,000,000     budget of every canvas up to RAMP_START
 *   RAMP_START   1,048,576 px    1024 x 1024, the largest canvas whose old
 *                                fixed-budget refusals are pinned by tests
 *   PER_PIXEL    24,576          units added per pixel above RAMP_START
 *   CAP          16,000,000,000  absolute ceiling, reached at 1,691,479 px
 * 1600 x 1000 (1,600,000 px) gets 13,751,796,224.
 * Worst case: a document that just fits the cap does 1.6e10 units. Measured
 * on the corpus (Release, Apple Silicon) at about 1.3 s per 1e9 units, so
 * about 21 s. The preflight and render allocate no per-unit memory (measured
 * 77 MB and 382 MB maximum RSS for 1.05e10 and 4.5e8 units), so the bytes
 * bound is the canvas plus the fixed per-shape tables, not the cap.
 * A document over the budget still fails with SVG_SHAPE_ERROR_LIMIT.
 */
#define RASTER_PREFLIGHT_BASE_WORK 200000000ULL
#define RASTER_PREFLIGHT_RAMP_START_PIXELS 1048576ULL
#define RASTER_PREFLIGHT_WORK_PER_PIXEL 24576ULL
#define RASTER_PREFLIGHT_WORK_CAP 16000000000ULL
#define RASTER_PREFLIGHT_SAMPLES_PER_AXIS 4U

static _Thread_local size_t preflight_work_limit = RASTER_PREFLIGHT_BASE_WORK;

size_t raster_preflight_work_budget(uint32_t width, uint32_t height)
{
    unsigned long long pixels = (unsigned long long)width * height;
    if (pixels <= RASTER_PREFLIGHT_RAMP_START_PIXELS)
        return (size_t)RASTER_PREFLIGHT_BASE_WORK;
    unsigned long long extra = pixels - RASTER_PREFLIGHT_RAMP_START_PIXELS;
    unsigned long long room = RASTER_PREFLIGHT_WORK_CAP - RASTER_PREFLIGHT_BASE_WORK;
    if (extra > room / RASTER_PREFLIGHT_WORK_PER_PIXEL)
        return (size_t)RASTER_PREFLIGHT_WORK_CAP;
    return (size_t)(RASTER_PREFLIGHT_BASE_WORK +
                    extra * RASTER_PREFLIGHT_WORK_PER_PIXEL);
}

static const double sample_locations[RASTER_PREFLIGHT_SAMPLES_PER_AXIS] = {
    0.125, 0.375, 0.625, 0.875
};

static bool work_add(size_t *total, size_t amount)
{
    if (*total > preflight_work_limit ||
        amount > preflight_work_limit - *total) return false;
    *total += amount;
    return true;
}

static bool checked_add_size(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool checked_mul_size(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static bool sample_is_in_view(const svg_shape_document *document,
                              double sample_x, double sample_y,
                              double scale_x, double scale_y,
                              double offset_x, double offset_y)
{
    double content_width = document->view_width * scale_x;
    double content_height = document->view_height * scale_y;
    return sample_x >= offset_x && sample_y >= offset_y &&
           sample_x < offset_x + content_width &&
           sample_y < offset_y + content_height;
}

static bool pixel_is_fully_in_view(const svg_shape_document *document,
                                   uint32_t x, uint32_t y,
                                   double scale_x, double scale_y,
                                   double offset_x, double offset_y)
{
    double content_width = document->view_width * scale_x;
    double content_height = document->view_height * scale_y;
    return (double)x >= offset_x && (double)y >= offset_y &&
           (double)x + 1.0 <= offset_x + content_width &&
           (double)y + 1.0 <= offset_y + content_height;
}

static size_t active_count_for(const size_t *shape_offsets, size_t stride,
                               size_t sample, size_t shape)
{
    size_t base = sample * stride;
    return shape_offsets[base + shape + 1U] - shape_offsets[base + shape];
}

static size_t sample_aux_work(const svg_shape_document *document, size_t shape,
                              bool *ok)
{
    size_t work = 0U;
    if (document->has_clips && document->clips != NULL &&
        document->clips[shape] != NULL &&
        !checked_add_size(work, svg_clip_work_units(document->clips[shape]),
                          &work)) {
        *ok = false;
        return 0U;
    }
    const svg_shape_paint *fill_paint =
        svg_shape_paint_for_shape(document, shape);
    if (fill_paint != NULL &&
        fill_paint->kind != SVG_SHAPE_PAINT_SOLID &&
        !checked_add_size(work, fill_paint->stop_count +
            (fill_paint->kind == SVG_SHAPE_PAINT_PATTERN ? 4U : 0U), &work)) {
        *ok = false;
        return 0U;
    }
    const svg_shape_paint *stroke_paint =
        svg_shape_stroke_paint_for_shape(document, shape);
    if (stroke_paint != NULL &&
        stroke_paint->kind != SVG_SHAPE_PAINT_SOLID) {
        size_t stroke_work = stroke_paint->stop_count;
        if (stroke_paint->kind == SVG_SHAPE_PAINT_PATTERN &&
            !checked_add_size(stroke_work, 4U, &stroke_work)) {
            *ok = false;
            return 0U;
        }
        if (!checked_add_size(work, stroke_work, &work)) {
            *ok = false;
            return 0U;
        }
    }
    return work;
}

static bool add_fast_sample(size_t sample_aux, size_t comparisons,
                            size_t *total, size_t *shape_samples,
                            size_t *fill_interval_tests)
{
    size_t sample_work;
    return checked_add_size(*fill_interval_tests, comparisons,
                            fill_interval_tests) &&
           work_add(total, comparisons) &&
           checked_add_size(1U, sample_aux, &sample_work) &&
           checked_add_size(*shape_samples, 1U, shape_samples) &&
           work_add(total, sample_work);
}

static bool count_fast_fill_intervals_for_runs(
    const svg_shape_document *document, const raster_pixel_bounds *box,
    uint32_t y, raster_fill_scanline_cache *fill_cache, size_t sample_row,
    double sample_x_offset, double sample_y, bool center_only,
    const raster_fill_pixel_run *runs, size_t run_count,
    double scale_x, double scale_y, double offset_x, double offset_y,
    size_t sample_aux, size_t *total, size_t *shape_samples,
    size_t *fill_interval_tests)
{
    size_t interval_count = fill_cache->interval_counts[sample_row];
    const raster_fill_scanline_interval *intervals = fill_cache->intervals +
        sample_row * fill_cache->interval_stride;
    for (size_t interval_index = 0U; interval_index < interval_count;
         interval_index++) {
        size_t first_x, end_x, comparisons = 0U;
        if (!raster_fill_scanline_interval_pixel_range(document, box, scale_x,
                offset_x, sample_x_offset, &intervals[interval_index],
                &first_x, &end_x, &comparisons) ||
            !checked_add_size(*fill_interval_tests, comparisons,
                              fill_interval_tests) ||
            !work_add(total, comparisons)) return false;
        for (size_t run_index = 0U; run_index < run_count; run_index++) {
            if (!checked_add_size(*fill_interval_tests, 1U,
                                  fill_interval_tests) ||
                !work_add(total, 1U)) return false;
            if (runs[run_index].center_only != center_only) continue;
            size_t first = first_x > runs[run_index].first_x ? first_x :
                           runs[run_index].first_x;
            size_t end = end_x < runs[run_index].end_x ? end_x :
                         runs[run_index].end_x;
            for (size_t x = first; x < end; x++) {
                if (!checked_add_size(*fill_interval_tests, 1U,
                                      fill_interval_tests) ||
                    !work_add(total, 1U)) return false;
                double sample_x = (double)x + sample_x_offset;
                if (!sample_is_in_view(document, sample_x, sample_y,
                        scale_x, scale_y, offset_x, offset_y)) continue;
                if (!add_fast_sample(sample_aux, 0U, total, shape_samples,
                                     fill_interval_tests)) return false;
            }
        }
    }
    (void)y;
    return true;
}

bool raster_shape_render_work_preflight(
    const svg_shape_document *document,
    const raster_shape_bounds_set *bounds,
    const raster_boundary_mask *boundary,
    raster_scanline_index *scanlines,
    size_t *shape_offsets,
    uint32_t *active_edges,
    size_t active_edge_capacity,
    uint32_t *active_shapes,
    const size_t *stroke_cost,
    const raster_shape_dash_cache *dash_cache,
    raster_fill_scanline_cache *fill_cache,
    double scale_x, double scale_y, double offset_x, double offset_y,
    raster_shape_work_stats *stats)
{
    if (document == NULL || bounds == NULL || boundary == NULL ||
        scanlines == NULL || shape_offsets == NULL ||
        (document->shape_count != 0U &&
         (active_shapes == NULL || stroke_cost == NULL)) ||
        fill_cache == NULL || stats == NULL ||
        (size_t)document->width > SIZE_MAX / (size_t)document->height) return false;
    size_t total = 0U;
    size_t pixels = (size_t)document->width * (size_t)document->height;
    preflight_work_limit =
        raster_preflight_work_budget(document->width, document->height);
    if (!work_add(&total, pixels) || !work_add(&total, bounds->pixel_count) ||
        !work_add(&total, boundary->mark_work) ||
        !work_add(&total, document->edge_count) ||
        !work_add(&total, document->shape_count)) return false;
    size_t levels = 1U;
    size_t tree_size = document->edge_count > document->shape_count ?
                       document->edge_count : document->shape_count;
    for (size_t n = tree_size; n > 1U; n = (n + 1U) / 2U) levels++;
    size_t event_count, event_factor, event_work;
    size_t scanline_levels = 1U;
    for (size_t n = scanlines->scanline_count; n > 1U; n = (n + 1U) / 2U)
        scanline_levels++;
    size_t lookup_factor, lookup_work, stroke_setup_work = 0U;
    for (size_t shape = 0U; shape < document->shape_count; shape++)
        if (!checked_add_size(stroke_setup_work, stroke_cost[shape],
                              &stroke_setup_work)) return false;
    if (dash_cache != NULL &&
        !checked_add_size(stroke_setup_work, dash_cache->build_steps,
                          &stroke_setup_work)) return false;
    if (dash_cache != NULL &&
        (!checked_add_size(stroke_setup_work, dash_cache->grid_cell_count,
                           &stroke_setup_work) ||
         !checked_add_size(stroke_setup_work, dash_cache->grid_ref_count,
                           &stroke_setup_work))) return false;
    if (!checked_add_size(scanlines->event_count, scanlines->shape_event_count,
                          &event_count) ||
        !checked_mul_size(levels, 6U, &event_factor) ||
        !checked_add_size(event_factor, 8U, &event_factor) ||
        !checked_mul_size(event_count, event_factor, &event_work) ||
        !work_add(&total, event_work) ||
        !checked_mul_size(scanline_levels, 2U, &lookup_factor) ||
        !checked_add_size(lookup_factor, 1U, &lookup_factor) ||
        !checked_mul_size(document->edge_count, lookup_factor, &lookup_work) ||
        !work_add(&total, lookup_work) || !work_add(&total, stroke_setup_work))
        return false;

    size_t shape_pixels = 0U, shape_samples = 0U;
    size_t fill_edge_tests = 0U, fill_interval_tests = 0U, stroke_tests = 0U;
    size_t shape_row_visits = 0U, stride;
    if (!checked_add_size(document->shape_count, 1U, &stride)) return false;
    size_t offsets_capacity;
    if (!checked_mul_size(stride, RASTER_SCANLINE_VALUES_PER_ROW,
                          &offsets_capacity)) return false;
    (void)offsets_capacity;
    raster_scanline_index_reset(scanlines);
    for (uint32_t y = 0U; y < document->height; y++) {
        size_t listed_before = scanlines->listed_edge_count;
        size_t active_shape_count = 0U;
        if (!raster_scanline_index_build_row(scanlines, y, shape_offsets,
                active_edges, active_edge_capacity, active_shapes,
                document->shape_count, &active_shape_count) ||
            !work_add(&total, scanlines->listed_edge_count - listed_before))
            return false;
        size_t row_visits;
        if (!checked_add_size(shape_row_visits, active_shape_count,
                              &shape_row_visits) ||
            !checked_mul_size(active_shape_count,
                              RASTER_SCANLINE_VALUES_PER_ROW + 1U, &row_visits) ||
            !work_add(&total, row_visits)) return false;
        for (size_t active = 0U; active < active_shape_count; active++) {
            size_t shape = active_shapes[active];
            const raster_pixel_bounds *box = &bounds->shapes[shape].pixels;
            if (!box->visible || y < box->y_first || y > box->y_last) return false;
            bool aux_ok = true;
            size_t aux_work = sample_aux_work(document, shape, &aux_ok);
            if (!aux_ok) return false;
            size_t edge_visits = 0U, setup_work = 0U;
            bool fast_fill = raster_fill_scanline_cache_is_eligible(fill_cache, shape) &&
                raster_fill_scanline_cache_build_row(fill_cache, document, shape, y,
                    scale_y, offset_y, shape_offsets, active_edges, stride,
                    &edge_visits, &setup_work);
            if (fast_fill) {
                size_t run_work = 0U;
                fast_fill = raster_fill_scanline_cache_build_pixel_runs(
                    fill_cache, document, box, y, boundary, scale_x, scale_y,
                    offset_x, offset_y, &run_work);
                if (fast_fill) {
                    size_t box_width = (size_t)box->x_last - box->x_first + 1U;
                    size_t run_count = 0U;
                    const raster_fill_pixel_run *runs =
                        raster_fill_scanline_cache_pixel_runs(fill_cache,
                                                              &run_count);
                    if (runs == NULL || run_count == 0U ||
                        !checked_add_size(fill_edge_tests, edge_visits,
                                          &fill_edge_tests) ||
                        !work_add(&total, setup_work) ||
                        !work_add(&total, run_work) ||
                        !checked_add_size(shape_pixels, box_width,
                                          &shape_pixels) ||
                        shape_pixels > bounds->pixel_count ||
                        !count_fast_fill_intervals_for_runs(document, box, y,
                            fill_cache, 2U, 0.5, (double)y + 0.5, true,
                            runs, run_count, scale_x, scale_y, offset_x,
                            offset_y, aux_work, &total, &shape_samples,
                            &fill_interval_tests)) return false;
                    for (size_t sy = 0U; sy < RASTER_PREFLIGHT_SAMPLES_PER_AXIS;
                         sy++) {
                        double sample_y = (double)y + sample_locations[sy];
                        size_t slot = sy < 2U ? sy : sy + 1U;
                        for (size_t sx = 0U; sx < RASTER_PREFLIGHT_SAMPLES_PER_AXIS;
                             sx++) {
                            if (!count_fast_fill_intervals_for_runs(document, box,
                                    y, fill_cache, slot, sample_locations[sx],
                                    sample_y, false, runs, run_count,
                                    scale_x, scale_y, offset_x, offset_y,
                                    aux_work, &total, &shape_samples,
                                    &fill_interval_tests)) return false;
                        }
                    }
                    continue;
                }
            }
            for (uint32_t x = box->x_first; x <= box->x_last; x++) {
                if (!checked_add_size(shape_pixels, 1U, &shape_pixels) ||
                    shape_pixels > bounds->pixel_count) return false;
                size_t pixel = (size_t)y * document->width + x;
                bool crisp_edges = document->strokes != NULL &&
                                   document->strokes[shape].crisp_edges;
                bool center_only = pixel_is_fully_in_view(document, x, y,
                    scale_x, scale_y, offset_x, offset_y) &&
                    (crisp_edges || !raster_boundary_mask_test(boundary, pixel));
                if (center_only) {
                    double sample_x = (double)x + 0.5;
                    double sample_y = (double)y + 0.5;
                    size_t edge_count = active_count_for(shape_offsets, stride,
                                                          2U, shape);
                    size_t sample_work;
                    bool stroke_indexed = false, stroke_candidates = false;
                    size_t sample_stroke_work = raster_shape_stroke_sample_work(
                        document, shape, dash_cache,
                        document->view_x + (sample_x - offset_x) / scale_x,
                        document->view_y + (sample_y - offset_y) / scale_y,
                        &stroke_indexed, &stroke_candidates);
                    if (!document->shape_filled[shape] && stroke_indexed &&
                        !stroke_candidates) {
                        if (!checked_add_size(stroke_tests, sample_stroke_work,
                                              &stroke_tests) ||
                            !work_add(&total, sample_stroke_work)) return false;
                        continue;
                    }
                    if (!document->shape_filled[shape] && stroke_indexed &&
                        !checked_add_size(sample_stroke_work, 1U,
                                          &sample_stroke_work)) return false;
                    if (!checked_add_size(1U, edge_count, &sample_work) ||
                        !checked_add_size(sample_work, sample_stroke_work,
                                          &sample_work) ||
                        !checked_add_size(sample_work, aux_work, &sample_work) ||
                        !checked_add_size(shape_samples, 1U, &shape_samples) ||
                        !checked_add_size(fill_edge_tests, edge_count,
                                          &fill_edge_tests) ||
                        !checked_add_size(stroke_tests, sample_stroke_work,
                                          &stroke_tests) ||
                        !work_add(&total, sample_work)) return false;
                    continue;
                }
                for (size_t sy = 0U; sy < RASTER_PREFLIGHT_SAMPLES_PER_AXIS;
                     sy++) {
                    double sample_y = (double)y + sample_locations[sy];
                    size_t active_slot = sy < 2U ? sy : sy + 1U;
                    size_t edge_count = active_count_for(shape_offsets, stride,
                                                          active_slot, shape);
                    for (size_t sx = 0U; sx < RASTER_PREFLIGHT_SAMPLES_PER_AXIS;
                         sx++) {
                        double sample_x = (double)x + sample_locations[sx];
                        if (!sample_is_in_view(document, sample_x, sample_y,
                                scale_x, scale_y, offset_x, offset_y)) continue;
                        size_t sample_work;
                        bool stroke_indexed = false, stroke_candidates = false;
                        size_t sample_stroke_work = raster_shape_stroke_sample_work(
                            document, shape, dash_cache,
                            document->view_x + (sample_x - offset_x) / scale_x,
                            document->view_y + (sample_y - offset_y) / scale_y,
                            &stroke_indexed, &stroke_candidates);
                        if (!document->shape_filled[shape] && stroke_indexed &&
                            !stroke_candidates) {
                            if (!checked_add_size(stroke_tests, sample_stroke_work,
                                                  &stroke_tests) ||
                                !work_add(&total, sample_stroke_work)) return false;
                            continue;
                        }
                        if (!document->shape_filled[shape] && stroke_indexed &&
                            !checked_add_size(sample_stroke_work, 1U,
                                              &sample_stroke_work)) return false;
                        if (!checked_add_size(1U, edge_count, &sample_work) ||
                            !checked_add_size(sample_work, sample_stroke_work,
                                              &sample_work) ||
                            !checked_add_size(sample_work, aux_work, &sample_work) ||
                            !checked_add_size(shape_samples, 1U, &shape_samples) ||
                            !checked_add_size(fill_edge_tests, edge_count,
                                              &fill_edge_tests) ||
                            !checked_add_size(stroke_tests, sample_stroke_work,
                                              &stroke_tests) ||
                            !work_add(&total, sample_work)) return false;
                    }
                }
            }
        }
    }
    if (shape_pixels != bounds->pixel_count) return false;
    stats->shape_pixels = (uint64_t)shape_pixels;
    stats->shape_samples = (uint64_t)shape_samples;
    stats->fill_edge_tests = (uint64_t)fill_edge_tests;
    stats->fill_interval_tests = (uint64_t)fill_interval_tests;
    stats->stroke_tests = (uint64_t)stroke_tests;
    stats->scanline_edge_entries = (uint64_t)scanlines->listed_edge_count;
    stats->shape_row_visits = (uint64_t)shape_row_visits;
    stats->boundary_mark_work = (uint64_t)boundary->mark_work;
    stats->total_work = (uint64_t)total;
    return true;
}

#include "shape_scanline_fill.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#define RASTER_FILL_SCANLINE_PIXEL_RUN_LIMIT (8U * 1024U * 1024U)

static const double sample_y_offsets[RASTER_FILL_SCANLINE_SAMPLE_ROWS] = {
    0.125, 0.375, 0.5, 0.625, 0.875
};

static bool checked_add_size(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool checked_mul_size(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static bool shape_is_uniform_filled(const svg_shape_document *document,
                                    size_t shape)
{
    if (document == NULL || shape >= document->shape_count ||
        document->shape_filled == NULL || !document->shape_filled[shape] ||
        document->shape_edge_start == NULL || document->shape_edge_count == NULL ||
        document->colors == NULL || document->strokes == NULL) return false;
    const svg_shape_stroke *stroke = &document->strokes[shape];
    if (stroke->rgba[3] != 0U && stroke->width > 0.0) return false;
    size_t first = document->shape_edge_start[shape];
    size_t count = document->shape_edge_count[shape];
    if (count == 0U || first > document->edge_count ||
        count > document->edge_count - first) return false;
    const uint8_t *color = document->colors + first * 4U;
    for (size_t edge = 1U; edge < count; edge++) {
        if (memcmp(color, document->colors + (first + edge) * 4U, 4U) != 0)
            return false;
    }
    return true;
}

static bool pixel_is_fully_in_view(const svg_shape_document *document,
                                   uint32_t x, uint32_t y,
                                   double scale_x, double scale_y,
                                   double offset_x, double offset_y)
{
    double content_width = document->view_width * scale_x;
    double content_height = document->view_height * scale_y;
    return (double)x >= offset_x && (double)y >= offset_y &&
           (double)x + 1.0 <= offset_x + content_width &&
           (double)y + 1.0 <= offset_y + content_height;
}

static bool crossing_less(const raster_fill_scanline_crossing *left,
                          const raster_fill_scanline_crossing *right)
{
    if (left->x < right->x) return true;
    if (left->x > right->x) return false;
    return left->edge_index < right->edge_index;
}

static void swap_crossings(raster_fill_scanline_crossing *left,
                           raster_fill_scanline_crossing *right)
{
    raster_fill_scanline_crossing temporary = *left;
    *left = *right;
    *right = temporary;
}

static void sift_down(raster_fill_scanline_crossing *values, size_t root,
                      size_t count)
{
    while (root < count / 2U) {
        size_t child = root * 2U + 1U;
        if (child + 1U < count && crossing_less(&values[child],
                                                &values[child + 1U]))
            child++;
        if (!crossing_less(&values[root], &values[child])) return;
        swap_crossings(&values[root], &values[child]);
        root = child;
    }
}

static void sort_crossings(raster_fill_scanline_crossing *values, size_t count)
{
    for (size_t parent = count / 2U; parent != 0U; parent--)
        sift_down(values, parent - 1U, count);
    for (size_t end = count; end > 1U; end--) {
        swap_crossings(&values[0], &values[end - 1U]);
        sift_down(values, 0U, end - 1U);
    }
}

static size_t ceil_log2(size_t value)
{
    size_t levels = 0U;
    size_t power = 1U;
    while (power < value) {
        if (power > SIZE_MAX / 2U) return sizeof(size_t) * 8U;
        power *= 2U;
        levels++;
    }
    return levels;
}

static bool build_intervals(const svg_shape_document *document, size_t shape,
                            double sample_y, const uint32_t *active_edges,
                            size_t active_count,
                            raster_fill_scanline_crossing *crossings,
                            size_t crossing_capacity,
                            raster_fill_scanline_interval *intervals,
                            size_t interval_capacity, size_t *out_interval_count,
                            size_t *out_edge_visits, size_t *out_work_units)
{
    *out_interval_count = 0U;
    if (active_count > crossing_capacity ||
        (active_count != 0U && active_edges == NULL)) return false;
    size_t crossing_count = 0U;
    for (size_t index = 0U; index < active_count; index++) {
        uint32_t edge_index = active_edges[index];
        if ((size_t)edge_index >= document->edge_count) return false;
        geom_edge edge = document->edges[edge_index];
        bool upward = edge.a.y <= sample_y && edge.b.y > sample_y;
        bool downward = edge.b.y <= sample_y && edge.a.y > sample_y;
        if (!upward && !downward) continue;
        double x = edge.a.x + (sample_y - edge.a.y) *
                   (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
        if (!isfinite(x)) return false;
        crossings[crossing_count++] = (raster_fill_scanline_crossing){
            x, upward ? 1 : -1, edge_index};
    }
    if (crossing_count > 1U) sort_crossings(crossings, crossing_count);
    int64_t winding = 0;
    uint8_t parity = 0U;
    for (size_t index = 0U; index < crossing_count; index++) {
        winding += crossings[index].winding_delta;
        parity ^= 1U;
    }
    if (crossing_count != 0U &&
        (document->shape_evenodd[shape] ? parity != 0U : winding != 0)) {
        if (interval_capacity == 0U) return false;
        intervals[(*out_interval_count)++] =
            (raster_fill_scanline_interval){-INFINITY, crossings[0].x};
    }
    size_t first = 0U;
    while (first < crossing_count) {
        size_t end = first + 1U;
        int64_t group_winding = crossings[first].winding_delta;
        uint8_t group_parity = 1U;
        while (end < crossing_count && crossings[end].x == crossings[first].x) {
            group_winding += crossings[end].winding_delta;
            group_parity ^= 1U;
            end++;
        }
        winding -= group_winding;
        parity ^= group_parity;
        double right = end < crossing_count ? crossings[end].x : INFINITY;
        bool inside = document->shape_evenodd[shape] ? parity != 0U : winding != 0;
        if (inside && crossings[first].x < right) {
            if (*out_interval_count >= interval_capacity) return false;
            intervals[(*out_interval_count)++] =
                (raster_fill_scanline_interval){crossings[first].x, right};
        }
        first = end;
    }
    *out_edge_visits = active_count;
    size_t sort_levels = ceil_log2(crossing_count > 1U ? crossing_count : 1U);
    size_t per_crossing, sort_work, scan_work;
    if (!checked_mul_size(sort_levels, 2U, &per_crossing) ||
        !checked_add_size(per_crossing, 6U, &per_crossing) ||
        !checked_mul_size(crossing_count, per_crossing, &sort_work) ||
        !checked_mul_size(active_count, 2U, &scan_work) ||
        !checked_add_size(sort_work, scan_work, out_work_units)) return false;
    return true;
}

bool raster_fill_scanline_cache_create(const svg_shape_document *document,
                                       raster_fill_scanline_cache *out_cache,
                                       svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
    if (out_cache == NULL) return false;
    *out_cache = (raster_fill_scanline_cache){0};
    if (document == NULL || (document->shape_count != 0U &&
        document->shape_count > SIZE_MAX / sizeof(*out_cache->eligible_shapes)))
        return false;
    if (document->shape_count == 0U) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    bool *eligible = calloc(document->shape_count, sizeof(*eligible));
    if (eligible == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    size_t max_edge_count = 0U;
    for (size_t shape = 0U; shape < document->shape_count; shape++) {
        size_t edge_count = document->shape_edge_count[shape];
        if (edge_count > RASTER_FILL_SCANLINE_MAX_EDGES ||
            !shape_is_uniform_filled(document, shape)) continue;
        eligible[shape] = true;
        if (edge_count > max_edge_count) max_edge_count = edge_count;
    }
    out_cache->eligible_shapes = eligible;
    out_cache->shape_count = document->shape_count;
    if (max_edge_count == 0U) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    if ((size_t)document->width >
        RASTER_FILL_SCANLINE_PIXEL_RUN_LIMIT / sizeof(*out_cache->pixel_runs)) {
        memset(eligible, 0, document->shape_count * sizeof(*eligible));
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
        return true;
    }
    size_t interval_stride, interval_count, crossing_bytes, interval_bytes;
    if (!checked_add_size(max_edge_count, 1U, &interval_stride) ||
        !checked_mul_size(interval_stride, RASTER_FILL_SCANLINE_SAMPLE_ROWS,
                          &interval_count) ||
        max_edge_count > SIZE_MAX / sizeof(*out_cache->crossings) ||
        interval_count > SIZE_MAX / sizeof(*out_cache->intervals)) {
        raster_fill_scanline_cache_destroy(out_cache);
        return false;
    }
    crossing_bytes = max_edge_count * sizeof(*out_cache->crossings);
    interval_bytes = interval_count * sizeof(*out_cache->intervals);
    out_cache->crossings = malloc(crossing_bytes);
    out_cache->intervals = malloc(interval_bytes);
    out_cache->pixel_run_capacity = document->width;
    out_cache->pixel_runs = malloc((size_t)document->width *
                                   sizeof(*out_cache->pixel_runs));
    if (out_cache->crossings == NULL || out_cache->intervals == NULL ||
        out_cache->pixel_runs == NULL) {
        raster_fill_scanline_cache_destroy(out_cache);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    out_cache->max_edge_count = max_edge_count;
    out_cache->interval_stride = interval_stride;
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0U};
    return true;
}

void raster_fill_scanline_cache_destroy(raster_fill_scanline_cache *cache)
{
    if (cache == NULL) return;
    free(cache->eligible_shapes);
    free(cache->crossings);
    free(cache->intervals);
    free(cache->pixel_runs);
    *cache = (raster_fill_scanline_cache){0};
}

bool raster_fill_scanline_cache_is_eligible(
    const raster_fill_scanline_cache *cache, size_t shape)
{
    return cache != NULL && cache->eligible_shapes != NULL &&
           shape < cache->shape_count && cache->eligible_shapes[shape];
}

const uint8_t *raster_fill_scanline_cache_color(
    const svg_shape_document *document, size_t shape)
{
    if (document == NULL || shape >= document->shape_count ||
        document->shape_edge_start == NULL || document->colors == NULL ||
        document->shape_edge_start[shape] >= document->edge_count) return NULL;
    return document->colors + document->shape_edge_start[shape] * 4U;
}

bool raster_fill_scanline_cache_build_row(
    raster_fill_scanline_cache *cache, const svg_shape_document *document,
    size_t shape, uint32_t pixel_y, double scale_y, double offset_y,
    const size_t *shape_offsets, const uint32_t *active_edges, size_t stride,
    size_t *out_edge_visits, size_t *out_work_units)
{
    if (out_edge_visits != NULL) *out_edge_visits = 0U;
    if (out_work_units != NULL) *out_work_units = 0U;
    if (!raster_fill_scanline_cache_is_eligible(cache, shape) ||
        document == NULL || shape_offsets == NULL || stride <= shape ||
        !isfinite(scale_y) || scale_y <= 0.0 || !isfinite(offset_y) ||
        cache->crossings == NULL || cache->intervals == NULL) return false;
    size_t edge_visits = 0U;
    size_t work_units = 0U;
    for (size_t sample = 0U; sample < RASTER_FILL_SCANLINE_SAMPLE_ROWS;
         sample++) {
        size_t base = sample * stride + shape;
        size_t first = shape_offsets[base];
        size_t end = shape_offsets[base + 1U];
        if (end < first || end - first > cache->max_edge_count) return false;
        size_t count = 0U, visits = 0U, work = 0U;
        double device_y = (double)pixel_y + sample_y_offsets[sample];
        double user_y = document->view_y + (device_y - offset_y) / scale_y;
        const uint32_t *edges = end == first || active_edges == NULL ? NULL :
                                active_edges + first;
        if (!build_intervals(document, shape, user_y, edges, end - first,
                cache->crossings, cache->max_edge_count,
                cache->intervals + sample * cache->interval_stride,
                cache->interval_stride, &count, &visits, &work) ||
            !checked_add_size(edge_visits, visits, &edge_visits) ||
            !checked_add_size(work_units, work, &work_units)) return false;
        cache->interval_counts[sample] = count;
    }
    if (out_edge_visits != NULL) *out_edge_visits = edge_visits;
    if (out_work_units != NULL) *out_work_units = work_units;
    return true;
}

bool raster_fill_scanline_cache_build_pixel_runs(
    raster_fill_scanline_cache *cache, const svg_shape_document *document,
    const raster_pixel_bounds *pixel_bounds, uint32_t pixel_y,
    const raster_boundary_mask *boundary, double scale_x, double scale_y,
    double offset_x, double offset_y, size_t *out_work_units)
{
    if (out_work_units != NULL) *out_work_units = 0U;
    if (cache == NULL || document == NULL || pixel_bounds == NULL ||
        boundary == NULL || boundary->bits == NULL || !pixel_bounds->visible ||
        pixel_y < pixel_bounds->y_first || pixel_y > pixel_bounds->y_last ||
        !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        !isfinite(offset_x) || !isfinite(offset_y) ||
        cache->pixel_runs == NULL) return false;
    cache->pixel_run_count = 0U;
    bool have_run = false;
    bool run_center_only = false;
    size_t run_width = 0U;
    uint32_t run_first = 0U;
    for (uint32_t x = pixel_bounds->x_first; ; x++) {
        size_t pixel = (size_t)pixel_y * document->width + x;
        bool center_only = pixel_is_fully_in_view(document, x, pixel_y,
                scale_x, scale_y, offset_x, offset_y) &&
            !raster_boundary_mask_test(boundary, pixel);
        if (!have_run || center_only != run_center_only) {
            if (have_run) {
                if (cache->pixel_run_count >= cache->pixel_run_capacity) return false;
                cache->pixel_runs[cache->pixel_run_count++] =
                    (raster_fill_pixel_run){run_first, x, run_center_only};
            }
            run_first = x;
            run_center_only = center_only;
            have_run = true;
        }
        run_width++;
        if (x == pixel_bounds->x_last) break;
    }
    if (have_run) {
        uint32_t end_x = pixel_bounds->x_last + 1U;
        if (cache->pixel_run_count >= cache->pixel_run_capacity) return false;
        cache->pixel_runs[cache->pixel_run_count++] =
            (raster_fill_pixel_run){run_first, end_x, run_center_only};
    }
    if (out_work_units != NULL) *out_work_units = run_width;
    return true;
}

const raster_fill_pixel_run *raster_fill_scanline_cache_pixel_runs(
    const raster_fill_scanline_cache *cache, size_t *out_run_count)
{
    if (out_run_count != NULL) *out_run_count = 0U;
    if (cache == NULL || cache->pixel_runs == NULL) return NULL;
    if (out_run_count != NULL) *out_run_count = cache->pixel_run_count;
    return cache->pixel_runs;
}

static size_t first_sample_x_at_least(const svg_shape_document *document,
                                      const raster_pixel_bounds *pixel_bounds,
                                      double scale_x, double offset_x,
                                      double sample_offset, double target,
                                      size_t *comparisons)
{
    size_t low = pixel_bounds->x_first;
    size_t high = (size_t)pixel_bounds->x_last + 1U;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        double device_x = (double)middle + sample_offset;
        double user_x = document->view_x + (device_x - offset_x) / scale_x;
        (*comparisons)++;
        if (user_x < target) low = middle + 1U;
        else high = middle;
    }
    return low;
}

bool raster_fill_scanline_interval_pixel_range(
    const svg_shape_document *document, const raster_pixel_bounds *pixel_bounds,
    double scale_x, double offset_x, double sample_offset,
    const raster_fill_scanline_interval *interval,
    size_t *out_first_x, size_t *out_end_x, size_t *out_comparisons)
{
    if (out_first_x != NULL) *out_first_x = 0U;
    if (out_end_x != NULL) *out_end_x = 0U;
    if (out_comparisons != NULL) *out_comparisons = 0U;
    if (document == NULL || pixel_bounds == NULL || interval == NULL ||
        out_first_x == NULL || out_end_x == NULL ||
        !pixel_bounds->visible || !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(offset_x) || !isfinite(sample_offset) ||
        isnan(interval->left) || isnan(interval->right) ||
        interval->right < interval->left) return false;
    size_t comparisons = 0U;
    size_t first = isinf(interval->left) && interval->left < 0.0 ?
        pixel_bounds->x_first : first_sample_x_at_least(document, pixel_bounds,
            scale_x, offset_x, sample_offset, interval->left, &comparisons);
    size_t end = isinf(interval->right) && interval->right > 0.0 ?
        (size_t)pixel_bounds->x_last + 1U :
        first_sample_x_at_least(document, pixel_bounds, scale_x, offset_x,
            sample_offset, interval->right, &comparisons);
    if (end < first) return false;
    *out_first_x = first;
    *out_end_x = end;
    if (out_comparisons != NULL) *out_comparisons = comparisons;
    return true;
}

bool raster_fill_scanline_cache_contains(
    const raster_fill_scanline_cache *cache, size_t sample_row, double x,
    size_t *out_comparisons)
{
    if (out_comparisons != NULL) *out_comparisons = 0U;
    if (cache == NULL || cache->intervals == NULL ||
        sample_row >= RASTER_FILL_SCANLINE_SAMPLE_ROWS || isnan(x)) return false;
    const raster_fill_scanline_interval *intervals =
        cache->intervals + sample_row * cache->interval_stride;
    size_t low = 0U;
    size_t high = cache->interval_counts[sample_row];
    size_t comparisons = 1U;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        comparisons++;
        if (intervals[middle].right <= x) low = middle + 1U;
        else high = middle;
    }
    if (out_comparisons != NULL) *out_comparisons = comparisons;
    return low < cache->interval_counts[sample_row] &&
           intervals[low].left <= x && x < intervals[low].right;
}

#include "shape_scanline.h"

#include <math.h>
#include <stdlib.h>

#define RASTER_SCANLINE_MAX_TREE_DEPTH 64U

static const double sample_y_offsets[RASTER_SCANLINE_VALUES_PER_ROW] = {
    0.125, 0.375, 0.5, 0.625, 0.875
};

static double user_scanline_y(const svg_shape_document *doc, size_t slot,
                              double scale_y, double offset_y)
{
    size_t pixel_y = slot / RASTER_SCANLINE_VALUES_PER_ROW;
    size_t sample = slot % RASTER_SCANLINE_VALUES_PER_ROW;
    double device_y = (double)pixel_y + sample_y_offsets[sample];
    return doc->view_y + (device_y - offset_y) / scale_y;
}

static size_t first_scanline_at_or_above(const svg_shape_document *doc,
                                         size_t count, double target,
                                         double scale_y, double offset_y)
{
    size_t low = 0U;
    size_t high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        double y = user_scanline_y(doc, middle, scale_y, offset_y);
        if (y < target) low = middle + 1U;
        else high = middle;
    }
    return low;
}

static int compare_events(const void *left_ptr, const void *right_ptr)
{
    const raster_scanline_event *left = left_ptr;
    const raster_scanline_event *right = right_ptr;
    if (left->slot < right->slot) return -1;
    if (left->slot > right->slot) return 1;
    if (left->edge < right->edge) return -1;
    if (left->edge > right->edge) return 1;
    if (left->add == right->add) return 0;
    return left->add ? 1 : -1;
}

static int compare_shape_events(const void *left_ptr, const void *right_ptr)
{
    const raster_shape_row_event *left = left_ptr;
    const raster_shape_row_event *right = right_ptr;
    if (left->row < right->row) return -1;
    if (left->row > right->row) return 1;
    if (left->add != right->add) return left->add ? 1 : -1;
    if (left->shape < right->shape) return -1;
    if (left->shape > right->shape) return 1;
    return 0;
}

static int32_t node_height(const raster_scanline_node *nodes, int32_t node)
{
    return node < 0 ? 0 : nodes[(size_t)node].height;
}

static void update_height(raster_scanline_node *nodes, int32_t node)
{
    int32_t left = nodes[(size_t)node].left;
    int32_t right = nodes[(size_t)node].right;
    int32_t left_height = node_height(nodes, left);
    int32_t right_height = node_height(nodes, right);
    nodes[(size_t)node].height = 1 + (left_height > right_height
                                        ? left_height : right_height);
}

static int32_t rotate_left(raster_scanline_node *nodes, int32_t root)
{
    int32_t pivot = nodes[(size_t)root].right;
    nodes[(size_t)root].right = nodes[(size_t)pivot].left;
    nodes[(size_t)pivot].left = root;
    update_height(nodes, root);
    update_height(nodes, pivot);
    return pivot;
}

static int32_t rotate_right(raster_scanline_node *nodes, int32_t root)
{
    int32_t pivot = nodes[(size_t)root].left;
    nodes[(size_t)root].left = nodes[(size_t)pivot].right;
    nodes[(size_t)pivot].right = root;
    update_height(nodes, root);
    update_height(nodes, pivot);
    return pivot;
}

static int32_t rebalance(raster_scanline_node *nodes, int32_t root)
{
    if (root < 0) return root;
    update_height(nodes, root);
    int32_t balance = node_height(nodes, nodes[(size_t)root].left) -
                      node_height(nodes, nodes[(size_t)root].right);
    if (balance > 1) {
        int32_t left = nodes[(size_t)root].left;
        if (node_height(nodes, nodes[(size_t)left].left) <
            node_height(nodes, nodes[(size_t)left].right))
            nodes[(size_t)root].left = rotate_left(nodes, left);
        return rotate_right(nodes, root);
    }
    if (balance < -1) {
        int32_t right = nodes[(size_t)root].right;
        if (node_height(nodes, nodes[(size_t)right].right) <
            node_height(nodes, nodes[(size_t)right].left))
            nodes[(size_t)root].right = rotate_right(nodes, right);
        return rotate_left(nodes, root);
    }
    return root;
}

static int32_t insert_node(raster_scanline_node *nodes, int32_t root,
                           int32_t key, size_t depth, bool *ok)
{
    if (depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) {
        *ok = false;
        return root;
    }
    if (root < 0) return key;
    if (key < root) {
        nodes[(size_t)root].left = insert_node(nodes, nodes[(size_t)root].left,
                                               key, depth + 1U, ok);
    } else if (key > root) {
        nodes[(size_t)root].right = insert_node(nodes, nodes[(size_t)root].right,
                                                key, depth + 1U, ok);
    } else {
        *ok = false;
        return root;
    }
    return *ok ? rebalance(nodes, root) : root;
}

static int32_t remove_node(raster_scanline_node *nodes, int32_t root,
                           int32_t key, size_t depth, bool *ok)
{
    if (root < 0 || depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) {
        *ok = false;
        return root;
    }
    if (key < root) {
        nodes[(size_t)root].left = remove_node(nodes, nodes[(size_t)root].left,
                                               key, depth + 1U, ok);
    } else if (key > root) {
        nodes[(size_t)root].right = remove_node(nodes, nodes[(size_t)root].right,
                                                key, depth + 1U, ok);
    } else {
        int32_t left = nodes[(size_t)root].left;
        int32_t right = nodes[(size_t)root].right;
        if (left < 0) return right;
        if (right < 0) return left;
        if (node_height(nodes, left) > node_height(nodes, right)) {
            root = rotate_right(nodes, root);
            nodes[(size_t)root].right = remove_node(
                nodes, nodes[(size_t)root].right, key, depth + 1U, ok);
        } else {
            root = rotate_left(nodes, root);
            nodes[(size_t)root].left = remove_node(
                nodes, nodes[(size_t)root].left, key, depth + 1U, ok);
        }
    }
    return *ok ? rebalance(nodes, root) : root;
}

static bool append_tree_in_order(const raster_scanline_node *nodes, int32_t root,
                                 uint32_t *destination, size_t capacity,
                                 size_t *cursor)
{
    int32_t stack[RASTER_SCANLINE_MAX_TREE_DEPTH];
    size_t depth = 0U;
    int32_t current = root;
    while (current >= 0 || depth != 0U) {
        while (current >= 0) {
            if (depth >= RASTER_SCANLINE_MAX_TREE_DEPTH) return false;
            stack[depth++] = current;
            current = nodes[(size_t)current].left;
        }
        current = stack[--depth];
        if (*cursor >= capacity) return false;
        destination[*cursor] = (uint32_t)current;
        (*cursor)++;
        current = nodes[(size_t)current].right;
    }
    return true;
}

bool raster_scanline_index_create(const svg_shape_document *doc,
                                  const raster_shape_bounds_set *bounds,
                                  double scale_y, double offset_y,
                                  raster_scanline_index *out,
                                  svg_shape_diagnostic *diagnostic)
{
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0};
    if (out == NULL) return false;
    *out = (raster_scanline_index){0};
    if (doc == NULL || bounds == NULL || bounds->shape_count != doc->shape_count ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        (size_t)doc->height > SIZE_MAX / RASTER_SCANLINE_VALUES_PER_ROW ||
        doc->edge_count > SIZE_MAX / 2U || doc->shape_count > SIZE_MAX / 2U ||
        doc->edge_count > INT32_MAX || doc->shape_count > INT32_MAX ||
        doc->edge_count > SIZE_MAX / sizeof(*out->nodes) ||
        doc->shape_count > SIZE_MAX / sizeof(*out->roots)) return false;
    size_t max_events = doc->edge_count * 2U;
    size_t max_shape_events = doc->shape_count * 2U;
    size_t scanline_count = (size_t)doc->height * RASTER_SCANLINE_VALUES_PER_ROW;
    raster_scanline_event *events = max_events == 0U ? NULL :
        malloc(max_events * sizeof(*events));
    raster_scanline_node *nodes = doc->edge_count == 0U ? NULL :
        malloc(doc->edge_count * sizeof(*nodes));
    int32_t *roots = doc->shape_count == 0U ? NULL :
        malloc(doc->shape_count * sizeof(*roots));
    raster_shape_row_event *shape_events = max_shape_events == 0U ? NULL :
        malloc(max_shape_events * sizeof(*shape_events));
    raster_scanline_node *shape_nodes = doc->shape_count == 0U ? NULL :
        malloc(doc->shape_count * sizeof(*shape_nodes));
    if ((max_events != 0U && events == NULL) ||
        (doc->edge_count != 0U && nodes == NULL) ||
        (doc->shape_count != 0U && (roots == NULL || shape_nodes == NULL)) ||
        (max_shape_events != 0U && shape_events == NULL)) {
        free(events); free(nodes); free(roots); free(shape_events); free(shape_nodes);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0};
        return false;
    }
    size_t shape_event_count = 0U;
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        roots[shape] = -1;
        const raster_pixel_bounds *box = &bounds->shapes[shape].pixels;
        if (!box->visible) continue;
        shape_events[shape_event_count++] = (raster_shape_row_event){
            box->y_first, (uint32_t)shape, true};
        shape_events[shape_event_count++] = (raster_shape_row_event){
            box->y_last + 1U, (uint32_t)shape, false};
    }
    size_t event_count = 0U;
    for (size_t edge_index = 0U; edge_index < doc->edge_count; edge_index++) {
        size_t shape = doc->shape_ids[edge_index];
        if (shape >= doc->shape_count) continue;
        geom_edge edge = doc->edges[edge_index];
        if (!doc->shape_filled[shape] || isnan(edge.a.y) || isnan(edge.b.y) ||
            edge.a.y == edge.b.y) continue;
        double low_y = fmin(edge.a.y, edge.b.y);
        double high_y = fmax(edge.a.y, edge.b.y);
        size_t first = first_scanline_at_or_above(doc, scanline_count, low_y,
                                                   scale_y, offset_y);
        size_t end = first_scanline_at_or_above(doc, scanline_count, high_y,
                                                 scale_y, offset_y);
        if (first >= end || first >= scanline_count) continue;
        if (end > scanline_count) end = scanline_count;
        events[event_count++] = (raster_scanline_event){first,
            (uint32_t)edge_index, true};
        events[event_count++] = (raster_scanline_event){end,
            (uint32_t)edge_index, false};
    }
    if (event_count > 1U) qsort(events, event_count, sizeof(*events), compare_events);
    if (shape_event_count > 1U)
        qsort(shape_events, shape_event_count, sizeof(*shape_events), compare_shape_events);
    out->document = doc;
    out->events = events;
    out->nodes = nodes;
    out->roots = roots;
    out->shape_events = shape_events;
    out->shape_nodes = shape_nodes;
    out->shape_root = -1;
    out->event_count = event_count;
    out->shape_event_count = shape_event_count;
    out->shape_count = doc->shape_count;
    out->edge_count = doc->edge_count;
    out->scanline_count = scanline_count;
    if (diagnostic != NULL)
        *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_NONE, 0};
    return true;
}

void raster_scanline_index_reset(raster_scanline_index *index)
{
    if (index == NULL) return;
    index->event_cursor = 0U;
    index->shape_event_cursor = 0U;
    index->listed_edge_count = 0U;
    index->shape_root = -1;
    for (size_t shape = 0U; shape < index->shape_count; shape++)
        index->roots[shape] = -1;
}

void raster_scanline_index_destroy(raster_scanline_index *index)
{
    if (index == NULL) return;
    free(index->events);
    free(index->nodes);
    free(index->roots);
    free(index->shape_events);
    free(index->shape_nodes);
    *index = (raster_scanline_index){0};
}

bool raster_scanline_index_build_row(raster_scanline_index *index,
                                     uint32_t pixel_y,
                                     size_t *shape_offsets,
                                     uint32_t *active_edges,
                                     size_t active_edge_capacity,
                                     uint32_t *active_shapes,
                                     size_t active_shape_capacity,
                                     size_t *active_shape_count)
{
    if (index == NULL || shape_offsets == NULL || active_shape_count == NULL ||
        (index->edge_count != 0U && active_edges == NULL) ||
        (index->shape_count != 0U && active_shapes == NULL) ||
        (size_t)pixel_y > SIZE_MAX / RASTER_SCANLINE_VALUES_PER_ROW) return false;
    *active_shape_count = 0U;
    while (index->shape_event_cursor < index->shape_event_count &&
           index->shape_events[index->shape_event_cursor].row <= pixel_y) {
        raster_shape_row_event event = index->shape_events[index->shape_event_cursor++];
        int32_t shape = (int32_t)event.shape;
        bool ok = true;
        if (event.add) {
            index->shape_nodes[event.shape] = (raster_scanline_node){-1, -1, 1};
            index->shape_root = insert_node(index->shape_nodes, index->shape_root,
                                            shape, 0U, &ok);
        } else {
            index->shape_root = remove_node(index->shape_nodes, index->shape_root,
                                            shape, 0U, &ok);
        }
        if (!ok) return false;
    }
    if (!append_tree_in_order(index->shape_nodes, index->shape_root, active_shapes,
                              active_shape_capacity, active_shape_count)) return false;
    size_t stride = index->shape_count + 1U;
    size_t write_cursor = 0U;
    for (size_t sample = 0U; sample < RASTER_SCANLINE_VALUES_PER_ROW; sample++) {
        size_t slot = (size_t)pixel_y * RASTER_SCANLINE_VALUES_PER_ROW + sample;
        while (index->event_cursor < index->event_count &&
               index->events[index->event_cursor].slot <= slot) {
            raster_scanline_event event = index->events[index->event_cursor++];
            size_t shape = index->document->shape_ids[event.edge];
            bool ok = true;
            if (event.add) {
                raster_scanline_node *node = &index->nodes[event.edge];
                *node = (raster_scanline_node){-1, -1, 1};
                index->roots[shape] = insert_node(index->nodes, index->roots[shape],
                    (int32_t)event.edge, 0U, &ok);
            } else {
                index->roots[shape] = remove_node(index->nodes, index->roots[shape],
                    (int32_t)event.edge, 0U, &ok);
            }
            if (!ok) return false;
        }
        size_t row_offset = sample * stride;
        for (size_t active = 0U; active < *active_shape_count; active++) {
            size_t shape = active_shapes[active];
            shape_offsets[row_offset + shape] = write_cursor;
            if (!append_tree_in_order(index->nodes, index->roots[shape], active_edges,
                                      active_edge_capacity, &write_cursor)) return false;
            shape_offsets[row_offset + shape + 1U] = write_cursor;
        }
    }
    index->listed_edge_count += write_cursor;
    return true;
}

        scanline_levels = add(scanline_levels, 1)?;
    }
    let mut stroke_setup = 0usize;
    for &c in scratch.stroke_cost.iter().take(view.shapes.len()) {
        poll(control, WorkKind::ShapeRowVisit)?;
        stroke_setup = add(stroke_setup, c)?;
    }
    stroke_setup = add(stroke_setup, scratch.dash.build_steps)?;
    stroke_setup = add(stroke_setup, scratch.dash.grid_cell_count)?;
    stroke_setup = add(stroke_setup, scratch.dash.grid_ref_count)?;
    let event_count = add(
        scratch.scanlines.events.len(),
        scratch.scanlines.shape_events.len(),
    )?;
    let event_work = mul(event_count, add(mul(levels, 6)?, 8)?)?;
    let lookup_work = mul(view.edges.len(), add(mul(scanline_levels, 2)?, 1)?)?;
    charge(&mut total, event_work, budget)?;
    charge(&mut total, lookup_work, budget)?;
    charge(&mut total, stroke_setup, budget)?;
    prepare_rows(&scratch.scanlines, &mut scratch.rows)?;
    reset_scanlines(&mut scratch.scanlines);
    let stride = add(view.shapes.len(), 1)?;
    let mut shape_pixels = 0usize;
    let mut shape_samples = 0usize;
    let mut fill_edge_tests = 0usize;
    let mut fill_interval_tests = 0usize;
    let mut stroke_tests = 0usize;
    let mut shape_row_visits = 0usize;
    for y in 0..view.viewport.height {
        poll(control, WorkKind::ShapePixel)?;
        let listed_before = scratch.scanlines.listed_edge_count;
        let active_shape_count = build_row(
            &mut scratch.scanlines,
            view,
            y,
            &mut scratch.rows,
            resources,
            control,
        )?;
        charge(
            &mut total,
            scratch.scanlines.listed_edge_count - listed_before,
            budget,
        )?;
        shape_row_visits = add(shape_row_visits, active_shape_count)?;
        charge(&mut total, mul(active_shape_count, 6)?, budget)?;
        for ai in 0..active_shape_count {
            poll(control, WorkKind::ShapeRowVisit)?;
            let shape = scratch.rows.active_shapes[ai] as usize;
            let bounds = scratch
                .bounds
                .shapes
                .get(shape)
                .ok_or_else(|| invalid(0))?
                .pixels;
            if !bounds.visible || y < bounds.y_first || y > bounds.y_last {
                return Err(invalid(source_offset(view, shape)));
            }
            let first_edge = view.shapes[shape].edges.first;
            let shape_id = view
                .edge_shape(first_edge)
                .ok_or_else(|| invalid(source_offset(view, shape)))?;
            let aux = aux_work(view, shape_id, resources, control)?;
            let row_work = if eligible(&scratch.fill, shape_id) {
                match build_fill_row(
                    &mut scratch.fill,
                    view,
                    shape_id,
                    y,
                    map,
                    &scratch.rows,
                    resources,
                    control,
                ) {
                    Ok(w) => Some(w),
                    Err(e)
                        if matches!(
                            e.kind,
                            ErrorKind::Canceled
                                | ErrorKind::OutOfMemory
                                | ErrorKind::Limit(
                                    LimitKind::Work | LimitKind::Arithmetic | LimitKind::Scratch
                                )
                        ) =>
                    {
                        return Err(e);
                    }
                    Err(_) => None,
                }
            } else {
                None
            };
            let run_work = if row_work.is_some() {
                match build_fill_runs(
                    &mut scratch.fill,
                    view,
                    bounds,
                    y,
                    &scratch.boundary,
                    map,
                    resources,
                    control,
                ) {
                    Ok(w) => Some(w),
                    Err(e)
                        if matches!(
                            e.kind,
                            ErrorKind::Canceled
                                | ErrorKind::OutOfMemory
                                | ErrorKind::Limit(
                                    LimitKind::Work | LimitKind::Arithmetic | LimitKind::Scratch
                                )
                        ) =>
                    {
                        return Err(e);
                    }
                    Err(_) => None,
                }
            } else {
                None
            };
            let fast = row_work.is_some() && run_work.is_some();
            if fast {
                let FillRowWork {
                    edge_visits,
                    work_units,
                } = row_work.ok_or_else(|| invalid(source_offset(view, shape)))?;
                let run_units = run_work.ok_or_else(|| invalid(source_offset(view, shape)))?;
                fill_edge_tests = add(fill_edge_tests, edge_visits)?;
                charge(&mut total, work_units, budget)?;
                charge(&mut total, run_units, budget)?;
                let runs = pixel_runs(&scratch.fill);
                if runs.is_empty() {
                    return Err(invalid(source_offset(view, shape)));
                }
                let width_box = (bounds.x_last - bounds.x_first) as usize + 1;
                shape_pixels = add(shape_pixels, width_box)?;
                if shape_pixels > scratch.bounds.pixel_count {
                    return Err(invalid(source_offset(view, shape)));
                }
                let sample_row = 2usize;
                let intervals = &scratch.fill.intervals[sample_row * scratch.fill.interval_stride
                    ..sample_row * scratch.fill.interval_stride
                        + scratch.fill.interval_counts[sample_row]];
                for interval in intervals {
                    poll(control, WorkKind::FillIntervalTest)?;
                    let (range, comparisons) =
                        interval_pixel_range(view, bounds, map, 0.5, *interval)?;
                    fill_interval_tests = add(fill_interval_tests, comparisons)?;
                    charge(&mut total, comparisons, budget)?;
                    for run in runs {
                        poll(control, WorkKind::FillIntervalTest)?;
                        fill_interval_tests = add(fill_interval_tests, 1)?;
                        charge(&mut total, 1, budget)?;
                        if !run.center_only {
                            continue;
                        }
                        let first = range.first.max(run.first_x as usize);
                        let end = (range.first + range.count).min(run.end_x as usize);
                        for x in first..end {
                            poll(control, WorkKind::FillIntervalTest)?;
                            fill_interval_tests = add(fill_interval_tests, 1)?;
                            charge(&mut total, 1, budget)?;
                            let sx = x as f64 + 0.5;
                            let sy = y as f64 + 0.5;
                            if !sample_in_view(view, sx, sy, map) {
                                continue;
                            }
                            shape_samples = add(shape_samples, 1)?;
                            charge(&mut total, add(1, aux)?, budget)?;
                        }
                    }
                }
                for (syi, &sample_y_offset) in SAMPLES.iter().enumerate() {
                    let sample_y = y as f64 + sample_y_offset;
                    let slot = if syi < 2 { syi } else { syi + 1 };
                    for &sample_x_offset in &SAMPLES {
                        poll(control, WorkKind::FillIntervalTest)?;
                        let row = slot;
                        let intervals = &scratch.fill.intervals[row * scratch.fill.interval_stride
                            ..row * scratch.fill.interval_stride
                                + scratch.fill.interval_counts[row]];
                        for interval in intervals {
                            poll(control, WorkKind::FillIntervalTest)?;
                            let (range, comparisons) = interval_pixel_range(
                                view,
                                bounds,
                                map,
                                sample_x_offset,
                                *interval,
                            )?;
                            fill_interval_tests = add(fill_interval_tests, comparisons)?;
                            charge(&mut total, comparisons, budget)?;
                            for run in runs {
                                poll(control, WorkKind::FillIntervalTest)?;
                                fill_interval_tests = add(fill_interval_tests, 1)?;
                                charge(&mut total, 1, budget)?;
                                if run.center_only {
                                    continue;
                                }
                                let first = range.first.max(run.first_x as usize);
                                let end = (range.first + range.count).min(run.end_x as usize);
                                for x in first..end {
                                    poll(control, WorkKind::FillIntervalTest)?;
                                    fill_interval_tests = add(fill_interval_tests, 1)?;
                                    charge(&mut total, 1, budget)?;
                                    let sample_x = x as f64 + sample_x_offset;
                                    if !sample_in_view(view, sample_x, sample_y, map) {
                                        continue;
                                    }
                                    shape_samples = add(shape_samples, 1)?;
                                    charge(&mut total, add(1, aux)?, budget)?;
                                }
                            }
                        }
                    }
                }
                continue;
            }
            for x in bounds.x_first..=bounds.x_last {
                poll(control, WorkKind::ShapePixel)?;
                shape_pixels = add(shape_pixels, 1)?;
                if shape_pixels > scratch.bounds.pixel_count {
                    return Err(invalid(source_offset(view, shape)));
                }
                let pixel = (y as usize) * width + x as usize;
                let crisp = view.shapes[shape].stroke.crisp_edges;
                let center_only = pixel_fully_in_view(view, x, y, map)
                    && (crisp || !crate::boundary_test(&scratch.boundary, pixel));
                if center_only {
                    let sample_x = x as f64 + 0.5;
                    let sample_y = y as f64 + 0.5;
                    let edges = active_count(&scratch.rows, stride, 2, shape)?;
                    let (mut sw, indexed, candidates) = stroke_work(
                        view,
                        shape_id,
                        resources,
                        scratch,
                        view.viewport.view_x + (sample_x - map.offset_x) / map.scale_x,
                        view.viewport.view_y + (sample_y - map.offset_y) / map.scale_y,
                        control,
                    )?;
                    if !view.shapes[shape].filled && indexed && !candidates {
                        stroke_tests = add(stroke_tests, sw)?;
                        charge(&mut total, sw, budget)?;
                        continue;
                    }
                    if !view.shapes[shape].filled && indexed {
                        sw = add(sw, 1)?;
                    }
                    let sample_work = add(add(add(1, edges)?, sw)?, aux)?;
                    shape_samples = add(shape_samples, 1)?;
                    fill_edge_tests = add(fill_edge_tests, edges)?;
                    stroke_tests = add(stroke_tests, sw)?;
                    charge(&mut total, sample_work, budget)?;
                    continue;
                }
                for (syi, &sample_y_offset) in SAMPLES.iter().enumerate() {
                    poll(control, WorkKind::ShapeSample)?;
                    let sample_y = y as f64 + sample_y_offset;
                    let slot = if syi < 2 { syi } else { syi + 1 };
                    let edges = active_count(&scratch.rows, stride, slot, shape)?;
                    for &sample_x_offset in &SAMPLES {
                        let sample_x = x as f64 + sample_x_offset;
                        if !sample_in_view(view, sample_x, sample_y, map) {
                            continue;
                        }
                        let (mut sw, indexed, candidates) = stroke_work(
                            view,
                            shape_id,
                            resources,
                            scratch,
                            view.viewport.view_x + (sample_x - map.offset_x) / map.scale_x,
                            view.viewport.view_y + (sample_y - map.offset_y) / map.scale_y,
                            control,
                        )?;
                        if !view.shapes[shape].filled && indexed && !candidates {
                            stroke_tests = add(stroke_tests, sw)?;
                            charge(&mut total, sw, budget)?;
                            continue;
                        }
                        if !view.shapes[shape].filled && indexed {
                            sw = add(sw, 1)?;
                        }
                        let sample_work = add(add(add(1, edges)?, sw)?, aux)?;
                        shape_samples = add(shape_samples, 1)?;
                        fill_edge_tests = add(fill_edge_tests, edges)?;
                        stroke_tests = add(stroke_tests, sw)?;
                        charge(&mut total, sample_work, budget)?;
                    }
                }
            }
        }
    }
    if shape_pixels != scratch.bounds.pixel_count {
        return Err(invalid(0));
    }
    let mut result = *stats;
    result.shape_pixels = u64::try_from(shape_pixels).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.shape_samples =
        u64::try_from(shape_samples).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.fill_edge_tests =
        u64::try_from(fill_edge_tests).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.fill_interval_tests =
        u64::try_from(fill_interval_tests).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.stroke_tests = u64::try_from(stroke_tests).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.scanline_edge_entries = u64::try_from(scratch.scanlines.listed_edge_count)
        .map_err(|_| limit(LimitKind::Arithmetic))?;
    result.shape_row_visits =
        u64::try_from(shape_row_visits).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.boundary_mark_work =
        u64::try_from(scratch.boundary.mark_work).map_err(|_| limit(LimitKind::Arithmetic))?;
    result.total_work = u64::try_from(total).map_err(|_| limit(LimitKind::Arithmetic))?;
    *stats = result;
    Ok(())
}

static bool clip_edge_pixel_bounds(const clip_boundary_context *context,
                                   geom_edge edge,
                                   raster_pixel_bounds *out)
{
    const svg_shape_document *doc = context->document;
    double x1 = context->offset_x + (edge.a.x - doc->view_x) * context->scale_x;
    double x2 = context->offset_x + (edge.b.x - doc->view_x) * context->scale_x;
    double y1 = context->offset_y + (edge.a.y - doc->view_y) * context->scale_y;
    double y2 = context->offset_y + (edge.b.y - doc->view_y) * context->scale_y;
    if (!isfinite(x1) || !isfinite(x2) || !isfinite(y1) || !isfinite(y2))
        return false;
    double epsilon = fmax(1.0, fmax(fabs(x1), fmax(fabs(x2),
                    fmax(fabs(y1), fabs(y2))))) * DBL_EPSILON * 8.0;
    uint32_t x_first, x_last, y_first, y_last;
    bool x_visible = boundary_pixel_range(fmin(x1, x2) - epsilon,
        fmax(x1, x2) + epsilon, doc->width, &x_first, &x_last);
    bool y_visible = boundary_pixel_range(fmin(y1, y2) - epsilon,
        fmax(y1, y2) + epsilon, doc->height, &y_first, &y_last);
    *out = x_visible && y_visible ?
        (raster_pixel_bounds){x_first, x_last, y_first, y_last, true} :
        (raster_pixel_bounds){0U, 0U, 0U, 0U, false};
    return true;
}

static bool add_clip_edge_work(clip_boundary_context *context, size_t amount)
{
    if (amount > RASTER_BOUNDARY_WORK_LIMIT - context->work) return false;
    context->work += amount;
    return true;
}

static bool preflight_clip_boundary_visits(const svg_shape_document *doc,
                                           raster_boundary_mask *boundary)
{
    size_t work = boundary->mark_work;
    size_t outer_shape_scans;
    if (!checked_mul_size(doc->shape_count, 3U, &outer_shape_scans) ||
        !checked_add_size(work, outer_shape_scans, &work)) {
        boundary->mark_work = SIZE_MAX;
        return false;
    }
    for (size_t shape = 0U; shape < doc->shape_count; shape++) {
        if (doc->clips[shape] == NULL) continue;
        svg_clip_work_counts counts;
        size_t visit_units, both_passes, preflight_units, total_units;
        if (!svg_clip_boundary_work_counts(doc->clips[shape], &counts) ||
            !checked_add_size(counts.chain_elements, counts.child_shapes,
                              &visit_units) ||
            !checked_mul_size(visit_units, 2U, &both_passes) ||
            !checked_add_size(counts.chain_elements, both_passes,
                              &preflight_units) ||
            !checked_add_size(work, preflight_units, &total_units)) {
            boundary->mark_work = SIZE_MAX;
            return false;
        }
        work = total_units;
    }
    boundary->mark_work = work;
    return work <= RASTER_BOUNDARY_WORK_LIMIT;
}

static bool visit_clip_boundary_edge(void *opaque, geom_edge edge)
{
    clip_boundary_context *context = opaque;
    raster_pixel_bounds box;
    if (!context->mark) {
        if (!clip_edge_pixel_bounds(context, edge, &box)) {
            context->force_full_mask = true;
            return add_clip_edge_work(context, 2U);
        }
        size_t amount = 2U;
        if (box.visible) {
            size_t width = (size_t)box.x_last - box.x_first + 1U;
            size_t height = (size_t)box.y_last - box.y_first + 1U;
            size_t area;
            if (!checked_mul_size(width, height, &area) ||
                !checked_add_size(amount, area, &amount)) return false;
        }
        return add_clip_edge_work(context, amount);
    }
    if (context->force_full_mask ||
        !clip_edge_pixel_bounds(context, edge, &box)) {
        context->force_full_mask = true;
        return true;
    }
    if (!box.visible) return true;
    for (uint32_t y = box.y_first; y <= box.y_last; y++) {
        size_t row = (size_t)y * context->document->width;
        for (uint32_t x = box.x_first; x <= box.x_last; x++)
            mark_pixel(context->boundary, row + x);
    }
    return true;
}

static bool mark_full_boundary_mask(clip_boundary_context *context)
{
    size_t pixels = context->boundary->bit_count;
    if (!add_clip_edge_work(context, pixels)) return false;
    for (size_t pixel = 0U; pixel < pixels; pixel++)
        mark_pixel(context->boundary, pixel);
    return true;
}

bool raster_shape_bounds_mark_clip_boundaries(
    const svg_shape_document *doc, double scale_x, double scale_y,
    double offset_x,
    double offset_y, raster_boundary_mask *boundary)
{
    if (doc == NULL || boundary == NULL || boundary->bits == NULL ||
        !isfinite(scale_x) || scale_x <= 0.0 ||
        !isfinite(scale_y) || scale_y <= 0.0 ||
        !isfinite(offset_x) || !isfinite(offset_y)) return false;
