#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct JobRowsState { pub edge_count: usize, pub shape_count: usize, pub next_y: u32 }

pub fn prepare_rows_job(index: &JobScanlineState, job: &mut RasterJob, scratch: &JobRasterScratch, backup: &JobRasterScratch, control: &mut dyn WorkControl) -> Result<JobRowsState> {
    let offsets = mul(add(index.shape_count, 1)?, 5)?;
    let edges = mul(index.edge_count, 5)?;
