fn insert(nodes: &mut [ScanlineNode], root: i32, key: i32, depth: i32, control: &mut dyn WorkControl) -> Result<i32> {
    poll(control, WorkKind::ScanlineEdgeEntry)?;
    if depth >= SCANLINE_MAX_TREE_DEPTH { return Err(limit(LimitKind::Work)); }
    if root < 0 { return Ok(key); }
    let i = root as usize;
    if key < root { nodes[i].left = insert(nodes, nodes[i].left, key, depth + 1, control)?; }
    else if key > root { nodes[i].right = insert(nodes, nodes[i].right, key, depth + 1, control)?; }
    else { return Err(limit(LimitKind::Work)); }
    Ok(rebalance(nodes, root))
}
fn remove(nodes: &mut [ScanlineNode], root: i32, key: i32, depth: i32, control: &mut dyn WorkControl) -> Result<i32> {
    poll(control, WorkKind::ScanlineEdgeEntry)?;
    if root < 0 || depth >= SCANLINE_MAX_TREE_DEPTH { return Err(limit(LimitKind::Work)); }
