    if (ok) ok = document.source.ptr == source && document.source.len == length &&
        CC_SHA256(source, (CC_LONG)length, after) != NULL &&
        memcmp(before, after, sizeof(before)) == 0;
    raster_tile_destroy(&tile);
    svg_shape_document_destroy(&document);
    return ok;
