/// Unique marked pixels, including correct masking of the final partial byte.
pub fn marked_pixel_count_job(job: &RasterJob, scratch: &JobRasterScratch, bit_count: usize, control: &mut dyn WorkControl) -> Result<usize> {
    let bytes = add(bit_count,7)? / 8;
